// Cache dinâmico de nações carregadas do banco
window.NACOES_BANCO_CACHE = [];

/**
 * Resolve qualquer valor de nação (ID numérico "1", sigla "USA", nome "Alemanha", etc.)
 * para o objeto padronizado com SVG/Bandeira, Sigla e Nome Completo.
 */
function resolverNacao(valor, basePath = "") {
    const v = String(valor || "USA").trim().toUpperCase();

    // Mapa direto de IDs e variações para a chave do NACOES_CONFIG
    const mapaChaves = {
        "1": "USA", "USA": "USA", "E.U.A.": "USA", "EUA": "USA", "ESTADOS UNIDOS": "USA",
        "2": "GER", "GER": "GER", "ALE": "GER", "ALEMANHA": "GER",
        "3": "RUS", "RUS": "RUS", "RÚS": "RUS", "URSS": "RUS", "RÚSSIA": "RUS", "RUSSIA": "RUS",
        "4": "JPN", "JPN": "JPN", "JAP": "JPN", "JAPÃO": "JPN", "JAPAO": "JPN",
        "5": "SWE", "SWE": "SWE", "SUÉ": "SWE", "SUE": "SWE", "SUÉCIA": "SWE", "SUECIA": "SWE",
        "6": "BRZ", "7": "BRZ", "BRZ": "BRZ", "BRA": "BRZ", "BRASIL": "BRZ"
    };

    const chaveConfig = mapaChaves[v];
    if (chaveConfig && NACOES_CONFIG[chaveConfig]) {
        return NACOES_CONFIG[chaveConfig];
    }

    // Se for uma nação nova criada dinamicamente no banco de dados
    const nacaoDinamica = window.NACOES_BANCO_CACHE.find(n =>
        String(n.Id || n.id) === v ||
        (n.nome || "").toUpperCase() === v ||
        (n.nome || "").substring(0, 3).toUpperCase() === v
    );

    if (nacaoDinamica) {
        const siglaDin = (nacaoDinamica.nome || "NAC").substring(0, 3).toUpperCase();
        const cor = nacaoDinamica.cor_hex || "#1d4ed8";
        return {
            id: String(nacaoDinamica.Id || nacaoDinamica.id),
            sigla: siglaDin,
            nome: (nacaoDinamica.nome || "NAÇÃO").toUpperCase(),
            corBorda: cor,
            glow: `${cor}80`,
            svg: `<img src="${basePath}${nacaoDinamica.caminho_bandeira}" style="width:22px;height:16px;object-fit:cover;border-radius:2px;display:block;flex-shrink:0;" onerror="this.style.display='none'">`
        };
    }

    return NACOES_CONFIG.USA;
}

/**
 * Gerenciador da Variável de Nação Favorita por Cliente (Isolada por Usuário)
 */
function obterChaveNacaoCliente() {
    const nick = (localStorage.getItem("userNickname") || "").trim().toLowerCase();
    return nick ? `userNation_${nick}` : "userNation_guest";
}

function obterNacaoFavoritaCliente() {
    const chaveCliente = obterChaveNacaoCliente();
    const valorSalvo = localStorage.getItem(chaveCliente) || localStorage.getItem("userNation") || "USA";
    return resolverNacao(valorSalvo).sigla;
}

function definirNacaoFavoritaCliente(valor) {
    const info = resolverNacao(valor);
    const chaveCliente = obterChaveNacaoCliente();
    localStorage.setItem(chaveCliente, info.sigla);
    localStorage.setItem("userNation", info.sigla);
    return info;
}

// Funções Utilitárias Globais
window.irParaNacao = function (e, id) {
    if (!e.target.closest(".admin-card-controls")) {
        window.location.href = `nacao.html?id=${id}`;
    }
};

const higienizarCaminho = (idInput) => {
    const el = document.getElementById(idInput);
    if (!el) return;
    el.addEventListener("input", function () {
        let val = this.value.replace(/"/g, "").replace(/\\/g, "/");
        const idx = val.indexOf("WT - Artes");
        if (idx !== -1) val = val.substring(idx);
        this.value = val;
    });
};

window.CATALOGO_TANQUES_WIKI = [];

const formatarTextoTatico = (txt, basePath = "") => {
    if (!txt) return "";
    let formatado = txt
        .replace(/\*\*(.*?)\*\*/g, '<strong style="color: #F2B400;">$1</strong>')
        .replace(/\n/g, "<br>");

    // 1. Converte marcações explícitas entre colchetes como [Tiger H1] ou [[Maus]]
    formatado = formatado.replace(/\[\[?(.*?)\]\]?/g, (match, nomeAlvo) => {
        const limpo = nomeAlvo.trim().toLowerCase();
        const achado = (window.CATALOGO_TANQUES_WIKI || []).find(t =>
            t.nome.toLowerCase() === limpo || t.nome.toLowerCase().includes(limpo)
        );
        if (achado) {
            return `<a href="${basePath}ficha.html?id=${achado.id}" class="wiki-inline-link" title="Abrir Dossiê: ${achado.nome}">🔗 ${nomeAlvo}</a>`;
        }
        return match;
    });

    // 2. Auto-Link Inteligente para nomes de tanques cadastrados no banco (exceto o tanque atual da página)
    const idAtual = new URLSearchParams(window.location.search).get("id");
    if (window.CATALOGO_TANQUES_WIKI && window.CATALOGO_TANQUES_WIKI.length > 0) {
        window.CATALOGO_TANQUES_WIKI.forEach(t => {
            if (String(t.id) === String(idAtual) || !t.nome || t.nome.length < 4) return;
            const escapado = t.nome.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
            const regex = new RegExp(`(?![^<]*>)(?<!🔗 )\\b(${escapado})\\b`, "i");
            formatado = formatado.replace(regex, `<a href="${basePath}ficha.html?id=${t.id}" class="wiki-inline-link" title="Ver Ficha Tática: ${t.nome}">$1</a>`);
        });
    }

    return formatado;
};

/**
 * 2. CENTRALIZADOR DE REQUISIÇÕES E SESSÃO (CSRF Automático)
 */
async function apiTatica(url, formData = null) {
    const opcoes = {
        method: formData ? "POST" : "GET",
        credentials: "same-origin",
        headers: {}
    };

    if (formData) {
        const token = localStorage.getItem("csrf_token") || "";
        if (!formData.has("csrf_token")) {
            formData.append("csrf_token", token);
        }
        opcoes.headers["X-CSRF-Token"] = token;
        opcoes.body = formData;
    }

    const req = await fetch(url, opcoes);
    const res = await req.json();

    if (req.status === 401 && res.code === "SESSION_EXPIRED") {
        localStorage.removeItem("isAuth");
        localStorage.removeItem("userRole");
        localStorage.removeItem("csrf_token");
        window.location.reload();
    }

    return { ok: req.ok, statusHttp: req.status, ...res };
}

async function sincronizarSessaoServidor(basePath) {
    try {
        const res = await apiTatica(`${basePath}php/api/usuarios.php?acao=verificar_sessao`);
        if (res.status === "success") {
            if (res.logado) {
                localStorage.setItem("isAuth", "true");
                localStorage.setItem("userRole", res.perfil);
                localStorage.setItem("userNickname", res.nickname);
                localStorage.setItem("csrf_token", res.csrf_token);
                if (res.nacao) {
                    definirNacaoFavoritaCliente(res.nacao);
                }
                if (window.atualizarControlesInterface) {
                    window.atualizarControlesInterface(true, res.perfil, basePath);
                }
            } else if (localStorage.getItem("isAuth") === "true") {
                localStorage.removeItem("isAuth");
                localStorage.removeItem("userRole");
                localStorage.removeItem("csrf_token");
                window.location.reload();
            }
        }
    } catch (e) {
        console.warn("Verificação de sessão offline:", e);
    }
}

