/**
 * 4. COMPONENTES DA BARRA SUPERIOR (Aba Tática, Relógio, Radar e Placa da Nação)
 */
function ativarAbaTatica() {
    const nav = document.querySelector(".top-navbar");
    const tab = document.getElementById("navPullTab");
    const icon = document.getElementById("pullTabIcon");
    if (!nav || !tab) return;

    document.body.style.paddingTop = nav.offsetHeight + "px";
    tab.addEventListener("click", () => {
        nav.classList.toggle("collapsed");
        if (nav.classList.contains("collapsed")) {
            icon.textContent = "keyboard_double_arrow_down";
            document.body.style.paddingTop = "30px";
        } else {
            icon.textContent = "keyboard_double_arrow_up";
            document.body.style.paddingTop = nav.offsetHeight + "px";
        }
    });
}

function iniciarRelogio() {
    const hh = document.getElementById("warHours");
    const mm = document.getElementById("warMinutes");
    const ss = document.getElementById("warSeconds");
    const dd = document.getElementById("warClockDate");
    if (!(hh && mm && ss && dd)) return;

    const meses = ["JAN", "FEV", "MAR", "ABR", "MAI", "JUN", "JUL", "AGO", "SET", "OUT", "NOV", "DEZ"];
    const atualizar = () => {
        const d = new Date();
        hh.textContent = String(d.getHours()).padStart(2, "0");
        mm.textContent = String(d.getMinutes()).padStart(2, "0");
        ss.textContent = String(d.getSeconds()).padStart(2, "0");
        dd.textContent = `${String(d.getDate()).padStart(2, "0")} ${meses[d.getMonth()]} ${d.getFullYear()}`;
    };
    atualizar();
    setInterval(atualizar, 1000);
}

function renderizarPlacaNacaoTopo(valorNacao, basePath = "") {
    const badge = document.getElementById("userNationBadge");
    if (!badge) return;

    const info = resolverNacao(valorNacao, basePath);
    badge.style.borderColor = info.corBorda;
    badge.style.boxShadow = `0 0 10px ${info.glow}`;
    badge.innerHTML = `
        <div style="display:flex;align-items:center;gap:6px;">
            ${info.svg}
            <span style="font-weight:bold;color:#fff;font-size:11px;">${info.sigla}</span>
        </div>
        <span style="font-size:9px;color:#aaa;">${info.nome}</span>
        <span style="font-size:8px;color:#F2B400;margin-left:2px;">▼</span>
    `;
}

function ativarRadarPesquisa(basePath) {
    const input = document.getElementById("searchInput");
    if (!input) return;

    const caixa = document.createElement("div");
    let timer;
    caixa.id = "radarResultados";
    caixa.className = "search-suggestions";
    input.parentElement.style.position = "relative";
    input.parentElement.appendChild(caixa);

    input.addEventListener("input", (e) => {
        const termo = e.target.value.trim();
        clearTimeout(timer);
        if (termo.length < 2) {
            caixa.style.display = "none";
            return;
        }
        timer = setTimeout(async () => {
            try {
                const res = await apiTatica(`${basePath}php/api/busca_veiculos.php?q=${encodeURIComponent(termo)}`);
                if (res.status === "success" && res.resultados.length > 0) {
                    caixa.innerHTML = res.resultados.map(t => `
                        <a href="${basePath}ficha.html?id=${t.id}" class="suggestion-link" style="padding: 12px; border-bottom: 1px solid #333; transition: background 0.2s;" onmouseover="this.style.background='#222'" onmouseout="this.style.background='transparent'">
                            <img src="${basePath}${t.caminho_imagem}?v=${Date.now()}" alt="${t.nome}" class="suggestion-icon" onerror="this.src='${basePath}WT - Artes/WT-ICO2.ico'">
                            <div style="display: flex; flex-direction: column;">
                                <span style="font-weight: bold; font-size: 13px; color: #F2B400;">${t.nome}</span>
                                <span style="font-size: 10px; color: #aaa;">${t.classe_veiculo || "Tanque"} | Nível ${t.nivel || "?"}</span>
                            </div>
                        </a>
                    `).join("");
                    caixa.style.display = "block";
                } else {
                    caixa.innerHTML = '<div style="padding: 15px; color: #ff4d4d; font-size: 12px; text-align: center; font-family: monospace;">Nenhum alvo detetado.</div>';
                    caixa.style.display = "block";
                }
            } catch (err) {
                console.error("Erro na busca do radar:", err);
            }
        }, 250);
    });

    document.addEventListener("click", (e) => {
        if (!input.contains(e.target) && !caixa.contains(e.target)) {
            caixa.style.display = "none";
        }
    });
}

/**
 * 5. AUTENTICAÇÃO, REGISTRO, RECUPERAÇÃO E PERFIL EM 2 ESTÁGIOS
 */
function iniciarLogin(basePath) {
    const modal = document.getElementById("loginModal");
    const btnLoginNav = document.querySelector(".btn-login");
    const btnClose = document.getElementById("closeModal");
    const form = document.getElementById("loginForm");
    const linkReg = document.getElementById("linkIrParaRegistro");
    const linkLog = document.getElementById("linkIrParaLogin");
    const btnRadar = document.getElementById("btnRadar");
    const radarIcon = document.getElementById("radarIcon");
    const inputEmail = document.getElementById("userEmail");
    const inputSenha = document.getElementById("userPassword");
    const btnSubmit = document.getElementById("btnSubmitLogin");

    if (linkReg) {
        linkReg.addEventListener("click", (e) => {
            e.preventDefault();
            modal.classList.remove("ativo");
            document.getElementById("registerModal").classList.add("ativo");
        });
    }
    if (linkLog) {
        linkLog.addEventListener("click", (e) => {
            e.preventDefault();
            document.getElementById("registerModal").classList.remove("ativo");
            modal.classList.add("ativo");
        });
    }
    if (btnRadar && inputSenha) {
        btnRadar.addEventListener("click", () => {
            if (inputSenha.type === "password") {
                inputSenha.type = "text";
                radarIcon.src = `${basePath}WT - Artes/UI-UX icons/Radar-ver.webp`;
            } else {
                inputSenha.type = "password";
                radarIcon.src = `${basePath}WT - Artes/UI-UX icons/Radar-ocultar.webp`;
            }
        });
    }

    if (!modal || !form) return;

    window.atualizarControlesInterface = function (estaLogado, role, path = basePath) {
        const isAdmin = estaLogado && (role || "").toLowerCase() === "admin";
        document.querySelectorAll(".admin-controls").forEach(el => {
            el.style.display = isAdmin ? "flex" : "none";
        });
        const badgeContainer = document.getElementById("userNationBadgeContainer");
        if (badgeContainer) {
            badgeContainer.style.display = estaLogado ? "flex" : "none";
            if (estaLogado) {
                renderizarPlacaNacaoTopo(obterNacaoFavoritaCliente(), path);
            }
        }
        const navLoginText = document.getElementById("navLoginText");
        if (navLoginText) navLoginText.textContent = estaLogado ? "PERFIL" : "ENTRAR";
    };

    const validarCampos = () => {
        const ok = inputEmail.value.includes("@") && inputSenha.value.length > 0;
        btnSubmit.disabled = !ok;
        btnSubmit.classList.toggle("valido", ok);
    };

    if (btnLoginNav) {
        btnLoginNav.addEventListener("click", (e) => {
            e.preventDefault();
            if (localStorage.getItem("isAuth") === "true") {
                const profileModal = document.getElementById("profileModal");
                profileModal.classList.add("ativo");
                if (window.abrirResumoPerfil) window.abrirResumoPerfil();
                if (window.carregarDadosPerfil) window.carregarDadosPerfil();
            } else {
                modal.classList.add("ativo");
            }
        });
    }

    if (btnClose) btnClose.addEventListener("click", () => modal.classList.remove("ativo"));
    inputEmail.addEventListener("input", validarCampos);
    inputSenha.addEventListener("input", validarCampos);

    form.addEventListener("submit", async (e) => {
        e.preventDefault();
        btnSubmit.disabled = true;
        btnSubmit.innerHTML = "AUTENTICANDO...";

        try {
            const fd = new FormData();
            fd.append("email", inputEmail.value);
            fd.append("senha", inputSenha.value);

            const req = await fetch(`${basePath}php/api/auth.php`, { method: "POST", body: fd });
            const res = await req.json();
            const feedback = document.getElementById("loginFeedback");

            if (req.ok && res.status === "success") {
                localStorage.setItem("isAuth", "true");
                localStorage.setItem("userRole", res.perfil);
                localStorage.setItem("userNickname", res.nickname);
                localStorage.setItem("csrf_token", res.csrf_token);
                definirNacaoFavoritaCliente(res.nacao_favorita || "USA");
                window.location.reload();
            } else if (res.status === "blocked") {
                feedback.style.display = "block";
                feedback.innerHTML = `Tentativas incorretas. Tente novamente em <span id="spanMinutos">${res.minutos_restantes}</span> minuto(s).`;
                btnSubmit.innerHTML = "ACESSO BLOQUEADO";
                btnSubmit.style.backgroundColor = "#555";
                if (window.timerBloqueioLogin) clearInterval(window.timerBloqueioLogin);
                let min = res.minutos_restantes;
                window.timerBloqueioLogin = setInterval(() => {
                    min--;
                    if (min <= 0) {
                        clearInterval(window.timerBloqueioLogin);
                        feedback.style.display = "none";
                        btnSubmit.innerHTML = "AUTENTICAR";
                        btnSubmit.style.backgroundColor = "";
                        btnSubmit.disabled = false;
                    } else {
                        document.getElementById("spanMinutos").textContent = min;
                    }
                }, 60000);
            } else {
                feedback.textContent = res.message;
                feedback.style.display = "block";
                btnSubmit.innerHTML = "FALHA";
                setTimeout(() => {
                    btnSubmit.innerHTML = "AUTENTICAR";
                    btnSubmit.disabled = false;
                }, 2000);
            }
        } catch (err) {
            btnSubmit.innerHTML = "AUTENTICAR";
            btnSubmit.disabled = false;
        }
    });

    // Estado inicial
    const estaLogado = localStorage.getItem("isAuth") === "true";
    const role = localStorage.getItem("userRole") || "visitante";
    window.atualizarControlesInterface(estaLogado, role, basePath);
}

function iniciarPerfil(basePath) {
    const modal = document.getElementById("profileModal");
    if (!modal) return;

    const btnClose = document.getElementById("closeProfileModal");
    const btnLogout = document.getElementById("btnLogout");
    const feedback = document.getElementById("profileFeedback");
    const subtitulo = document.getElementById("profileSubtituloModal");

    // Estágio 1 vs Estágio 2
    const painelResumo = document.getElementById("painelPerfilResumo");
    const painelEditar = document.getElementById("painelPerfilEditar");
    const btnIrEditar = document.getElementById("btnIrParaAtualizarDados");
    const btnVoltarResumo = document.getElementById("btnVoltarResumoPerfil");

    // Abas internas do Estágio 2 ("Atualizar Dados")
    const tabDados = document.getElementById("tabDados");
    const tabSenha = document.getElementById("tabSenha");
    const formDados = document.getElementById("formPerfilDados");
    const formSenha = document.getElementById("formPerfilSenha");

    btnClose.addEventListener("click", () => modal.classList.remove("ativo"));

    // Alternar para Estágio 1 (Visualização do Dossiê)
    window.abrirResumoPerfil = () => {
        painelResumo.style.display = "block";
        painelEditar.style.display = "none";
        feedback.style.display = "none";
        if (subtitulo) subtitulo.textContent = "Credencial de Identificação Militar";
    };

    // Alternar para Estágio 2 (Página "Atualizar Dados")
    if (btnIrEditar) {
        btnIrEditar.addEventListener("click", () => {
            painelResumo.style.display = "none";
            painelEditar.style.display = "block";
            feedback.style.display = "none";
            if (subtitulo) subtitulo.textContent = "Atualização Cadastral e Criptográfica";
            tabDados.click();
        });
    }

    if (btnVoltarResumo) {
        btnVoltarResumo.addEventListener("click", () => {
            window.abrirResumoPerfil();
        });
    }

    // Sub-aba 1: Dados Complementares
    tabDados.addEventListener("click", () => {
        tabDados.style.background = "#F2B400";
        tabDados.style.color = "#000";
        tabSenha.style.background = "#333";
        tabSenha.style.color = "#fff";
        formDados.style.display = "block";
        formSenha.style.display = "none";
        feedback.style.display = "none";
    });

    // Sub-aba 2: Alterar Senha
    tabSenha.addEventListener("click", () => {
        tabSenha.style.background = "#F2B400";
        tabSenha.style.color = "#000";
        tabDados.style.background = "#333";
        tabDados.style.color = "#fff";
        formSenha.style.display = "block";
        formDados.style.display = "none";
        feedback.style.display = "none";
    });

    // Carregar e Renderizar Dados no Cartão de Leitura e nos Inputs
    window.carregarDadosPerfil = async () => {
        try {
            const res = await apiTatica(`${basePath}php/api/perfil.php?acao=get`);
            if (res.status === "success" && res.dados) {
                const u = res.dados;
                const msgNaoInformado = '<span style="color:#777; font-style:italic;">Não informado — Atualize seu dossiê</span>';

                // 1. Preenche o Cartão de Leitura (Estágio 1)
                document.getElementById("viewPerfilNick").textContent = u.nickname || localStorage.getItem("userNickname") || "Comandante";

                const isAdm = (u.perfil || localStorage.getItem("userRole") || "").toLowerCase() === "admin";
                const elPatente = document.getElementById("viewPerfilPatente");
                elPatente.textContent = isAdm ? "ALTO COMANDO (ADMIN)" : "SOLDADO ATIVO";
                elPatente.style.background = isAdm ? "#F2B400" : "#333";
                elPatente.style.color = isAdm ? "#000" : "#fff";

                const nacaoInfo = resolverNacao(u.nacao_favorita || obterNacaoFavoritaCliente(), basePath);
                const elNacao = document.getElementById("viewPerfilNacaoBadge");
                elNacao.style.borderColor = nacaoInfo.corBorda;
                elNacao.innerHTML = `${nacaoInfo.svg} <span>${nacaoInfo.sigla} • ${nacaoInfo.nome}</span>`;

                const nomeCivil = `${u.nome || ""} ${u.sobrenome || ""}`.trim();
                document.getElementById("viewPerfilNomeCompleto").innerHTML = nomeCivil ? nomeCivil : msgNaoInformado;
                document.getElementById("viewPerfilEmailPrincipal").innerHTML = u.email ? u.email : msgNaoInformado;
                document.getElementById("viewPerfilEmailContato").innerHTML = (u.email_contato && u.email_contato.trim() !== "") ? u.email_contato : msgNaoInformado;
                document.getElementById("viewPerfilTelefone").innerHTML = (u.telefone && u.telefone.trim() !== "") ? u.telefone : msgNaoInformado;

                // 2. Preenche os Inputs do Formulário (Estágio 2)
                document.getElementById("perfilNick").value = u.nickname || "";
                document.getElementById("perfilNome").value = u.nome || "";
                document.getElementById("perfilSobrenome").value = u.sobrenome || "";
                document.getElementById("perfilEmailContato").value = u.email_contato || "";
                document.getElementById("perfilTelefone").value = u.telefone || "";
            }
        } catch (e) {
            console.error("Erro ao carregar perfil:", e);
        }
    };

    // Submissão: Atualizar Dados Complementares
    formDados.addEventListener("submit", async (e) => {
        e.preventDefault();
        const btn = document.getElementById("btnSalvarPerfil");
        btn.disabled = true;
        btn.innerHTML = "SALVANDO...";

        const fd = new FormData();
        fd.append("acao", "update_dados");
        fd.append("nome", document.getElementById("perfilNome").value);
        fd.append("sobrenome", document.getElementById("perfilSobrenome").value);
        fd.append("email_contato", document.getElementById("perfilEmailContato").value);
        fd.append("telefone", document.getElementById("perfilTelefone").value);
        fd.append("senha_atual", document.getElementById("perfilSenhaAtualDados").value);

        try {
            const res = await apiTatica(`${basePath}php/api/perfil.php`, fd);
            feedback.style.display = "block";
            feedback.style.borderLeft = res.status === "success" ? "4px solid #4caf50" : "4px solid var(--rus-vermelho)";
            feedback.style.background = res.status === "success" ? "#122a18" : "#2a1212";
            feedback.style.color = res.status === "success" ? "#80ff9f" : "#ff8080";
            feedback.textContent = res.message;

            if (res.status === "success") {
                document.getElementById("perfilSenhaAtualDados").value = "";
                await window.carregarDadosPerfil();
                setTimeout(() => window.abrirResumoPerfil(), 1200);
            }
        } catch (err) {
            feedback.textContent = "Erro de conexão.";
            feedback.style.display = "block";
        }
        btn.disabled = false;
        btn.innerHTML = "SALVAR DADOS COMPLEMENTARES";
    });

    // Submissão: Alterar Senha
    formSenha.addEventListener("submit", async (e) => {
        e.preventDefault();
        const nova = document.getElementById("perfilNovaSenha").value;
        if (nova !== document.getElementById("perfilConfirmarSenha").value) {
            feedback.style.display = "block";
            feedback.style.borderLeft = "4px solid var(--rus-vermelho)";
            feedback.style.background = "#2a1212";
            feedback.style.color = "#ff8080";
            feedback.textContent = "As novas senhas não coincidem.";
            return;
        }

        const btn = document.getElementById("btnSalvarNovaSenha");
        btn.disabled = true;
        btn.innerHTML = "PROCESSANDO...";

        const fd = new FormData();
        fd.append("acao", "update_senha");
        fd.append("senha_atual", document.getElementById("perfilSenhaAtual").value);
        fd.append("nova_senha", nova);

        try {
            const res = await apiTatica(`${basePath}php/api/perfil.php`, fd);
            feedback.style.display = "block";
            feedback.style.borderLeft = res.status === "success" ? "4px solid #4caf50" : "4px solid var(--rus-vermelho)";
            feedback.style.background = res.status === "success" ? "#122a18" : "#2a1212";
            feedback.style.color = res.status === "success" ? "#80ff9f" : "#ff8080";
            feedback.textContent = res.message;
            if (res.status === "success") formSenha.reset();
        } catch (err) {
            feedback.textContent = "Erro de conexão.";
            feedback.style.display = "block";
        }
        btn.disabled = false;
        btn.innerHTML = "APLICAR NOVA SENHA";
    });

    // Logout (Preserva a variável de nação individual de cada cliente)
    btnLogout.addEventListener("click", async () => {
        try {
            await fetch(`${basePath}php/api/logout.php`);
            localStorage.removeItem("isAuth");
            localStorage.removeItem("userRole");
            localStorage.removeItem("userNickname");
            localStorage.removeItem("csrf_token");
            window.location.reload();
        } catch (e) {}
    });
}

function iniciarRegistro(basePath) {
    let iti;
    const modal = document.getElementById("registerModal");
    const btnClose = document.getElementById("closeRegisterModal");
    const form = document.getElementById("registerForm");
    if (!modal || !form) return;

    const nome = document.getElementById("regNome");
    const sobrenome = document.getElementById("regSobrenome");
    const nick = document.getElementById("regNickname");
    const email = document.getElementById("regEmail");
    const senha = document.getElementById("regSenha");
    const confirmar = document.getElementById("regConfirmar");
    const erroSenha = document.getElementById("regErroSenha");
    const feedback = document.getElementById("registerFeedback");
    const btnSubmit = document.getElementById("btnSubmitRegister");
    const btnRadar = document.getElementById("btnRadarReg");
    const radarIcon = document.getElementById("radarIconReg");
    const tel = document.getElementById("regTelefone");

    if (window.intlTelInput && tel) {
        iti = window.intlTelInput(tel, {
            initialCountry: "br",
            utilsScript: "https://cdn.jsdelivr.net/npm/intl-tel-input@23.0.10/build/js/utils.js"
        });
    }

    if (btnRadar) {
        btnRadar.addEventListener("click", () => {
            if (senha.type === "password") {
                senha.type = "text";
                radarIcon.src = `${basePath}WT - Artes/UI-UX icons/Radar-ver.webp`;
            } else {
                senha.type = "password";
                radarIcon.src = `${basePath}WT - Artes/UI-UX icons/Radar-ocultar.webp`;
            }
        });
    }

    const limparAvisos = () => {
        if (erroSenha) erroSenha.style.display = "none";
        if (feedback) feedback.style.display = "none";
    };

    const checarForm = () => {
        const ok = nome.value.trim().length > 0 && sobrenome.value.trim().length > 0 &&
                   nick.value.trim().length > 0 && email.value.includes("@") &&
                   senha.value.length > 0 && confirmar.value.length > 0;
        btnSubmit.disabled = !ok;
        btnSubmit.classList.toggle("valido", ok);
    };

    [nome, sobrenome, nick, email, senha, confirmar].forEach(el => {
        el.addEventListener("input", () => { limparAvisos(); checarForm(); });
    });

    if (btnClose) {
        btnClose.addEventListener("click", () => {
            modal.classList.remove("ativo");
            form.reset();
            limparAvisos();
            checarForm();
        });
    }

    form.addEventListener("submit", async (e) => {
        e.preventDefault();
        limparAvisos();

        if (senha.value !== confirmar.value) {
            erroSenha.textContent = "AS CHAVES CRIPTOGRÁFICAS NÃO COINCIDEM.";
            erroSenha.style.display = "block";
            return;
        }
        const s = senha.value;
        if (s.length < 8 || !/[A-Z]/.test(s) || !/[a-z]/.test(s) || !/\d/.test(s) || !/[\W_]/.test(s)) {
            erroSenha.textContent = "A CHAVE DEVE TER MÍN. 8 CARACTERES, MAIÚSCULAS, MINÚSCULAS, NÚMEROS E SÍMBOLOS.";
            erroSenha.style.display = "block";
            return;
        }

        btnSubmit.disabled = true;
        const txtOrig = btnSubmit.innerHTML;
        btnSubmit.innerHTML = "PROCESSANDO...";

        try {
            const fd = new FormData();
            fd.append("nome", nome.value);
            fd.append("sobrenome", sobrenome.value);
            fd.append("nickname", nick.value);
            fd.append("email", email.value);
            fd.append("email_contato", document.getElementById("regEmailContato").value);
            fd.append("telefone", iti ? iti.getNumber() : tel.value);
            fd.append("senha", senha.value);

            const req = await fetch(`${basePath}php/api/register.php`, { method: "POST", body: fd });
            const res = await req.json();

            if (req.ok && res.status === "success") {
                btnSubmit.innerHTML = "ALISTAMENTO CONCLUÍDO!";
                btnSubmit.style.backgroundColor = "#4caf50";
                setTimeout(() => {
                    modal.classList.remove("ativo");
                    form.reset();
                    btnSubmit.innerHTML = txtOrig;
                    btnSubmit.style.backgroundColor = "";
                    checarForm();
                    document.getElementById("loginModal").classList.add("ativo");
                }, 1500);
            } else {
                feedback.textContent = res.message;
                feedback.style.display = "block";
                btnSubmit.innerHTML = txtOrig;
                checarForm();
            }
        } catch (err) {
            feedback.textContent = "Erro interno no servidor.";
            feedback.style.display = "block";
            btnSubmit.innerHTML = txtOrig;
            checarForm();
        }
    });
}

function iniciarRecuperacaoSenha(basePath) {
    const btnOpen = document.getElementById("esqueciSenhaBtn");
    const modal = document.getElementById("recoverModal");
    const btnClose = document.getElementById("closeRecoverModal");
    const recoverForm = document.getElementById("recoverForm");
    const resetForm = document.getElementById("resetForm");
    const feedback = document.getElementById("recoverFeedback");
    if (!modal) return;

    if (btnOpen) {
        btnOpen.addEventListener("click", (e) => {
            e.preventDefault();
            document.getElementById("loginModal").classList.remove("ativo");
            modal.classList.add("ativo");
            if (feedback) feedback.style.display = "none";
        });
    }
    if (btnClose) btnClose.addEventListener("click", () => modal.classList.remove("ativo"));

    if (recoverForm) {
        recoverForm.addEventListener("submit", async (e) => {
            e.preventDefault();
            const btn = document.getElementById("btnSubmitRecover");
            const orig = btn.innerHTML;
            btn.disabled = true;
            btn.innerHTML = "LOCALIZANDO...";
            try {
                const fd = new FormData();
                fd.append("email", document.getElementById("recoverEmail").value);
                const req = await fetch(`${basePath}php/api/recover.php`, { method: "POST", body: fd });
                const res = await req.json();
                feedback.style.display = "block";
                feedback.textContent = res.message;
                if (res.status === "success") {
                    recoverForm.style.display = "none";
                    resetForm.style.display = "block";
                }
            } catch (err) {
                feedback.style.display = "block";
                feedback.textContent = "Falha ao contactar a central.";
            } finally {
                btn.innerHTML = orig;
                btn.disabled = false;
            }
        });
    }

    if (resetForm) {
        resetForm.addEventListener("submit", async (e) => {
            e.preventDefault();
            const btn = document.getElementById("btnSubmitReset");
            const orig = btn.innerHTML;
            btn.disabled = true;
            btn.innerHTML = "REDEFININDO...";
            try {
                const fd = new FormData();
                fd.append("token", document.getElementById("resetToken").value);
                fd.append("nova_senha", document.getElementById("resetSenha").value);
                const req = await fetch(`${basePath}php/api/reset_password.php`, { method: "POST", body: fd });
                const res = await req.json();
                feedback.style.display = "block";
                feedback.textContent = res.message;
                if (res.status === "success") {
                    setTimeout(() => {
                        modal.classList.remove("ativo");
                        resetForm.reset();
                        recoverForm.reset();
                        recoverForm.style.display = "block";
                        resetForm.style.display = "none";
                        document.getElementById("loginModal").classList.add("ativo");
                    }, 1800);
                }
            } catch (err) {
                feedback.style.display = "block";
                feedback.textContent = "Erro ao redefinir a credencial.";
            } finally {
                btn.innerHTML = orig;
                btn.disabled = false;
            }
        });
    }
}

/**
 * 6. GESTÃO DE TROPAS E LIVRO DE REGISTROS (Com Bandeira e Nome da Nação)
 */
function iniciarTropas(basePath) {
    const modal = document.getElementById("tropasModal");
    const btnOpen = document.getElementById("btnOpenTropas");
    const btnClose = document.getElementById("closeTropasModal");
    const tbody = document.getElementById("listaSoldadosTbody");
    const tbodyLogs = document.getElementById("listaLogsTbody");
    const feedback = document.getElementById("tropasFeedback");

    const inputBusca = document.getElementById("buscaSoldadoInput");
    const selectOrdem = document.getElementById("ordenaSoldadosSelect");
    const selectNacao = document.getElementById("filtroNacaoSelect");

    const tabSoldados = document.getElementById("tabTropasSoldados");
    const tabAuditoria = document.getElementById("tabTropasAuditoria");
    const painelSoldados = document.getElementById("painelSoldados");
    const painelAuditoria = document.getElementById("painelAuditoria");

    if (!modal || !btnOpen || !tbody) return;

    let todosSoldados = [];

    function exibirFeedback(msg, sucesso = true) {
        if (!feedback) return;
        feedback.style.display = "block";
        feedback.style.borderLeft = sucesso ? "4px solid #4caf50" : "4px solid var(--rus-vermelho)";
        feedback.style.background = sucesso ? "#122a18" : "#2a1212";
        feedback.style.color = sucesso ? "#80ff9f" : "#ff8080";
        feedback.textContent = msg;
        setTimeout(() => { feedback.style.display = "none"; }, 4000);
    }

    // Alternância das Abas Efetivo Ativo <-> Livro de Registros (Logs)
    if (tabSoldados && tabAuditoria) {
        tabSoldados.addEventListener("click", () => {
            tabSoldados.style.backgroundColor = "#F2B400";
            tabSoldados.style.color = "#000";
            tabAuditoria.style.backgroundColor = "#333";
            tabAuditoria.style.color = "#fff";
            painelSoldados.style.display = "flex";
            painelAuditoria.style.display = "none";
        });

        tabAuditoria.addEventListener("click", () => {
            tabAuditoria.style.backgroundColor = "#F2B400";
            tabAuditoria.style.color = "#000";
            tabSoldados.style.backgroundColor = "#333";
            tabSoldados.style.color = "#fff";
            painelSoldados.style.display = "none";
            painelAuditoria.style.display = "block";
            carregarLogs();
        });
    }

    btnOpen.addEventListener("click", (e) => {
        e.preventDefault();
        modal.classList.add("ativo");
        if (tabSoldados) tabSoldados.click();
        carregarTropas();
    });

    if (btnClose) btnClose.addEventListener("click", () => modal.classList.remove("ativo"));

    async function carregarTropas() {
        tbody.innerHTML = '<tr><td colspan="6" style="text-align: center; padding: 20px; color: #F2B400;">Sincronizando dossiês com o Comando Central...</td></tr>';
        try {
            const res = await apiTatica(`${basePath}php/api/usuarios.php?acao=listar`);
            if (res.status === "success") {
                todosSoldados = res.dados || res.usuarios || [];
                renderizarTabela();
            } else {
                tbody.innerHTML = `<tr><td colspan="6" style="text-align: center; color: #ff4d4d; padding: 20px;">${res.message || "Acesso negado."}</td></tr>`;
            }
        } catch (err) {
            tbody.innerHTML = '<tr><td colspan="6" style="text-align: center; color: #ff4d4d; padding: 20px;">Falha ao sincronizar dados com o servidor.</td></tr>';
        }
    }

    async function carregarLogs() {
        if (!tbodyLogs) return;
        tbodyLogs.innerHTML = '<tr><td colspan="5" style="text-align:center; padding:20px; color:#F2B400;">Descriptografando Livro de Registros...</td></tr>';
        try {
            const res = await apiTatica(`${basePath}php/api/usuarios.php?acao=listar_logs`);
            const logs = res.logs || [];
            if (logs.length === 0) {
                tbodyLogs.innerHTML = '<tr><td colspan="5" style="text-align:center; padding:20px; color:#aaa;">Nenhum registro tático no livro de auditoria.</td></tr>';
                return;
            }
            
            tbodyLogs.innerHTML = logs.map(log => {
                // Define o Verde como cor padrão para criações e atualizações normais
                let corAcao = "#80ff9f"; 
                const acaoTxt = (log.acao || "").toUpperCase();

                // Lógica de Semântica de Cores
                if (acaoTxt.includes("EXCLUÍDA") || acaoTxt.includes("OBLITERADO") || acaoTxt.includes("EXCLUÍDO")) {
                    corAcao = "#ff4d4d"; // Vermelho para exclusões
                } else if (acaoTxt.includes("PATENTE") || acaoTxt.includes("STATUS")) {
                    corAcao = "#F2B400"; // Dourado para alterações de membros
                }

                return `
                <tr style="border-bottom: 1px solid #222;">
                    <td style="padding: 10px 8px; color:#F2B400; font-weight:bold;">${log.admin_nickname}</td>
                    <td style="padding: 10px 8px; color:#fff;">${log.alvo_nickname}</td>
                    <td style="padding: 10px 8px; color:${corAcao}; font-weight:bold;">${log.acao}</td>
                    <td style="padding: 10px 8px; color:#aaa;">${log.detalhes}</td>
                    <td style="padding: 10px 8px; color:#888;">${log.data_hora}</td>
                </tr>
                `;
            }).join("");
            
        } catch (err) {
            tbodyLogs.innerHTML = '<tr><td colspan="5" style="text-align:center; padding:20px; color:#ff4d4d;">Erro ao carregar o Livro de Registros.</td></tr>';
        }
    }

    function renderizarTabela() {
        const termo = (inputBusca ? inputBusca.value : "").toLowerCase();
        const filtroNacao = selectNacao ? selectNacao.value : "TODAS";
        const ordem = selectOrdem ? selectOrdem.value : "recente";

        let filtrados = todosSoldados.filter(s => {
            const nick = (s.nickname || "").toLowerCase();
            const mail = (s.email || "").toLowerCase();
            const nacaoObj = resolverNacao(s.nacao_favorita, basePath);

            const matchBusca = nick.includes(termo) || mail.includes(termo);
            const matchNacao = filtroNacao === "TODAS" || nacaoObj.sigla === filtroNacao;
            return matchBusca && matchNacao;
        });

        filtrados.sort((a, b) => {
            if (ordem === "recente") return b.id - a.id;
            if (ordem === "antigo") return a.id - b.id;
            if (ordem === "az") return (a.nickname || "").localeCompare(b.nickname || "");
            if (ordem === "za") return (b.nickname || "").localeCompare(a.nickname || "");
            return 0;
        });

        if (filtrados.length === 0) {
            tbody.innerHTML = '<tr><td colspan="6" style="text-align: center; padding: 20px; color:#aaa;">Nenhum soldado encontrado nestas coordenadas.</td></tr>';
            return;
        }

        tbody.innerHTML = filtrados.map(user => {
            const isAtivo = user.status === "ativo";
            const isAdmin = user.perfil === "admin";
            const badgeStyle = isAdmin ? "background:#F2B400;color:#000;" : "background:#333;color:#fff;";
            const statusColor = isAtivo ? "#4caf50" : "#ff4d4d";
            const btnStatusTexto = isAtivo ? "SUSPENDER" : "REATIVAR";
            const btnStatusBg = isAtivo ? "var(--rus-vermelho)" : "#4caf50";
            const proximoStatus = isAtivo ? "inativo" : "ativo";
            const proximaPatente = isAdmin ? "visitante" : "admin";

            // Resolve a Bandeira e o Nome Completo da Nação do Soldado
            const nacaoObj = resolverNacao(user.nacao_favorita, basePath);

            return `
                <tr style="border-bottom: 1px solid #222;">
                    <td style="padding: 10px 8px; font-weight:bold; color:#fff;">${user.nickname}</td>
                    <td style="padding: 10px 8px; color:#aaa;">${user.email}</td>
                    <td style="padding: 10px 8px;">
                        <div style="display:inline-flex; align-items:center; gap:7px; background:#111; border:1px solid ${nacaoObj.corBorda}; padding:4px 8px; border-radius:4px;">
                            ${nacaoObj.svg}
                            <span style="font-size:11px; color:#fff; font-weight:bold;">${nacaoObj.sigla} • ${nacaoObj.nome}</span>
                        </div>
                    </td>
                    <td style="padding: 10px 8px;">
                        <span style="${badgeStyle} padding:3px 7px; border-radius:3px; font-size:10px; font-weight:bold; cursor:pointer;" 
                              title="Clique para alternar patente"
                              onclick="window.alterarPatenteTropa(${user.id}, '${proximaPatente}')">
                            ${(user.perfil || "visitante").toUpperCase()} &#8645;
                        </span>
                    </td>
                    <td style="padding: 10px 8px; color:${statusColor}; font-weight:bold;">${(user.status || "ativo").toUpperCase()}</td>
                    <td style="padding: 10px 8px; text-align:center;">
                        <button type="button" class="btn-submit-militar" 
                                style="padding:6px 10px; font-size:10px; width:auto; margin:0; display:inline-flex; background:${btnStatusBg}; color:#fff;" 
                                onclick="window.alterarStatusTropa(${user.id}, '${proximoStatus}')">
                            ${btnStatusTexto}
                        </button>
                    </td>
                </tr>
            `;
        }).join("");
    }

    if (inputBusca) inputBusca.addEventListener("input", renderizarTabela);
    if (selectOrdem) selectOrdem.addEventListener("change", renderizarTabela);
    if (selectNacao) selectNacao.addEventListener("change", renderizarTabela);

    window.alterarStatusTropa = async (id, novoStatus) => {
        if (!confirm(`Confirma a alteração de status para ${novoStatus.toUpperCase()}?`)) return;
        const fd = new FormData();
        fd.append("acao", "alterar_status");
        fd.append("id_usuario", id);
        fd.append("status", novoStatus);

        try {
            const res = await apiTatica(`${basePath}php/api/usuarios.php`, fd);
            exibirFeedback(res.message, res.status === "success");
            if (res.status === "success") {
                const alvo = todosSoldados.find(u => u.id == id);
                if (alvo) alvo.status = res.novo_status || novoStatus;
                renderizarTabela();
            }
        } catch (e) {
            exibirFeedback("Erro de comunicação com o Comando Central.", false);
        }
    };

    window.alterarPatenteTropa = async (id, novaPatente) => {
        if (!confirm(`Deseja alterar a patente deste soldado para ${novaPatente.toUpperCase()}?`)) return;
        const fd = new FormData();
        fd.append("acao", "mudar_perfil");
        fd.append("usuario_id", id);
        fd.append("novo_perfil", novaPatente);

        try {
            const res = await apiTatica(`${basePath}php/api/usuarios.php`, fd);
            exibirFeedback(res.message, res.status === "success");
            if (res.status === "success") {
                const alvo = todosSoldados.find(u => u.id == id);
                if (alvo) alvo.perfil = res.novo_perfil || novaPatente;
                renderizarTabela();
            }
        } catch (e) {
            exibirFeedback("Erro ao alterar patente.", false);
        }
    };
}

/**
 * 7. PÁGINAS DINÂMICAS: INDEX, NAÇÃO E FICHA TÉCNICA
 */
function iniciarIndex(basePath) {
    const carrossel = document.getElementById("nacoesCarrossel");
    if (!carrossel) return;

    const btnNova = document.getElementById("btnNovaNacao");
    const modal = document.getElementById("modalGerenciarNacao");
    const btnClose = document.getElementById("closeNacaoModalX");
    const role = (localStorage.getItem("userRole") || "").toLowerCase();
    let nacoes = [];

    if (btnClose) btnClose.addEventListener("click", () => modal.classList.remove("ativo"));

    if (role === "admin" && btnNova) {
        btnNova.style.display = "block";
        btnNova.addEventListener("click", () => {
            document.getElementById("formGerenciarNacao").reset();
            document.getElementById("nacaoId").value = "";
            document.getElementById("tituloModalNacao").textContent = "FUNDAR NOVA NAÇÃO";
            modal.classList.add("ativo");
        });

        higienizarCaminho("nacaoBandeira");
        higienizarCaminho("nacaoSilhueta");

        document.getElementById("formGerenciarNacao").addEventListener("submit", async (e) => {
            e.preventDefault();
            const btn = document.getElementById("btnSalvarNacao");
            btn.disabled = true;
            btn.innerHTML = "PROCESSANDO...";

            const fd = new FormData();
            fd.append("acao", "salvar_nacao");
            fd.append("id", document.getElementById("nacaoId").value);
            fd.append("nome", document.getElementById("nacaoNome").value);
            fd.append("cor", document.getElementById("nacaoCor").value);
            fd.append("bandeira", document.getElementById("nacaoBandeira").value);
            fd.append("silhueta", document.getElementById("nacaoSilhueta").value);
            fd.append("resumo", document.getElementById("nacaoResumo").value);

            try {
                const res = await apiTatica(`${basePath}php/api/admin_index_api.php`, fd);
                if (res.ok && res.status === "success") {
                    window.location.reload();
                } else {
                    alert("Erro: " + res.message);
                    btn.disabled = false;
                    btn.innerHTML = "SALVAR NAÇÃO";
                }
            } catch (err) {
                btn.disabled = false;
                btn.innerHTML = "SALVAR NAÇÃO";
            }
        });
    }

    (async () => {
        try {
            const res = await apiTatica(`${basePath}php/api/listar_nacoes.php`);
            if (res.status === "success") {
                nacoes = res.nacoes;
                if (document.getElementById("contadorNacoes")) {
                    document.getElementById("contadorNacoes").textContent = `${nacoes.length} NAÇÕES`;
                }
                carrossel.innerHTML = nacoes.map(n => {
                    const controles = role === "admin" ? `
                        <div class="admin-card-controls">
                            <button class="btn-admin-card btn-editar-nacao" data-id="${n.Id}" style="background: #F2B400; color: #000;"><span class="material-symbols-outlined" style="font-size: 16px;">edit</span></button>
                            <button class="btn-admin-card btn-excluir-nacao" data-id="${n.Id}" style="background: var(--rus-vermelho); color: #fff;"><span class="material-symbols-outlined" style="font-size: 16px;">delete</span></button>
                        </div>
                    ` : "";

                    return `
                        <div class="nation-card nation-bg card-custom-${n.Id}" onclick="irParaNacao(event, ${n.Id})"
                             style="background-color: #555555; background-image: url('${basePath}${n.caminho_bandeira}?v=${Date.now()}'); background-size: cover; background-position: center; background-blend-mode: multiply; border-color: ${n.cor_hex};">
                            ${controles}
                            <h1 class="nation-title" style="text-shadow: 2px 2px 5px #000;">${n.nome.toUpperCase()}</h1>
                            <img class="tank-silhueta" src="${basePath}${n.icone_silhueta || "WT - Artes/WT-ICO2.ico"}?v=${Date.now()}" alt="Silhueta de ${n.nome}" onerror="this.src='${basePath}WT - Artes/WT-ICO2.ico'">
                            <div class="card-info-box" style="border-top: 2px solid ${n.cor_hex}; box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.5);">
                                <p>"${n.resumo_card || "Força Militar em estruturação."}"</p>
                            </div>
                        </div>
                    `;
                }).join("");

                document.querySelectorAll(".btn-editar-nacao").forEach(btn => {
                    btn.addEventListener("click", (e) => {
                        const id = e.currentTarget.getAttribute("data-id");
                        const obj = nacoes.find(x => x.Id == id);
                        document.getElementById("nacaoId").value = obj.Id;
                        document.getElementById("nacaoNome").value = obj.nome;
                        document.getElementById("nacaoCor").value = obj.cor_hex;
                        document.getElementById("nacaoBandeira").value = obj.caminho_bandeira || "";
                        document.getElementById("nacaoSilhueta").value = obj.icone_silhueta || "";
                        document.getElementById("nacaoResumo").value = obj.resumo_card || "";
                        document.getElementById("tituloModalNacao").textContent = "EDITAR DADOS DA NAÇÃO";
                        modal.classList.add("ativo");
                    });
                });

                document.querySelectorAll(".btn-excluir-nacao").forEach(btn => {
                    btn.addEventListener("click", async (e) => {
                        const id = e.currentTarget.getAttribute("data-id");
                        const obj = nacoes.find(x => x.Id == id);
                        if (confirm(`ALERTA SEVERO:\nDeletar a nação "${obj.nome}" destruirá todos os tanques associados a ela.\nProsseguir?`)) {
                            const fd = new FormData();
                            fd.append("acao", "excluir_nacao");
                            fd.append("id", id);
                            const r = await apiTatica(`${basePath}php/api/admin_index_api.php`, fd);
                            if (r.ok) window.location.reload();
                        }
                    });
                });
            }
        } catch (err) {}
    })();
}

function iniciarNacao(basePath) {
    const container = document.getElementById("nacaoContainer");
    if (!container) return;

    const nacaoId = new URLSearchParams(window.location.search).get("id");
    const loading = document.getElementById("loadingOverlay");
    const lista = document.getElementById("listaTanques");
    const btnEditar = document.getElementById("btnEditarNacao");
    const btnNovo = document.getElementById("btnNovoTanque");
    const modal = document.getElementById("edicaoNacaoModal");
    const role = (localStorage.getItem("userRole") || "").toLowerCase();

    if (!nacaoId) {
        if (loading) loading.innerHTML = "<span style='color:red;'>Nação não identificada.</span>";
        return;
    }

    const btnClose = document.getElementById("closeNacaoModal");
    if (btnClose) btnClose.addEventListener("click", () => modal.classList.remove("ativo"));
    higienizarCaminho("editNacaoBandeira");

    const form = document.getElementById("formEdicaoNacao");
    if (form) {
        form.addEventListener("submit", async (e) => {
            e.preventDefault();
            const btn = document.getElementById("btnSalvarNacao");
            btn.disabled = true;
            btn.innerHTML = "ATUALIZANDO...";
            try {
                const fd = new FormData();
                fd.append("acao", "salvar_nacao");
                fd.append("id", document.getElementById("editNacaoId").value);
                fd.append("nome", document.getElementById("editNacaoNome").value);
                fd.append("cor", document.getElementById("editNacaoCor").value);
                fd.append("bandeira", document.getElementById("editNacaoBandeira").value);
                fd.append("lore", document.getElementById("editNacaoLore").value);
                fd.append("silhueta", form.dataset.silhueta || "");
                fd.append("resumo", form.dataset.resumo || "");
                const r = await apiTatica(`${basePath}php/api/admin_index_api.php`, fd);
                if (r.ok) window.location.reload();
            } catch (err) {
                btn.disabled = false;
                btn.innerHTML = "ERRO";
            }
        });
    }

    (async () => {
        try {
            const res = await apiTatica(`${basePath}php/api/listar_frota_nacao.php?nacao_id=${nacaoId}`);
            if (res.status === "success") {
                const n = res.nacao;
                const tanques = res.tanques;
                document.title = `${n.nome.toUpperCase()} - War Thunder`;
                document.getElementById("dinNomeNacao").textContent = n.nome.toUpperCase();
                document.getElementById("dinBandeira").src = `${basePath}${n.caminho_bandeira || ""}?v=${Date.now()}`;
                document.getElementById("bannerContainer").style.borderBottomColor = n.cor_hex !== "#ffffff" ? n.cor_hex : "#444";
                document.getElementById("dinLoreNacao").innerHTML = n.lore_taticas ? formatarTextoTatico(n.lore_taticas) : "<p class='paragraph'>Doutrina militar confidencial.</p>";

                if (tanques.length > 0) {
                    lista.innerHTML = tanques.map((t, idx) => `
                        <a href="${basePath}ficha.html?id=${t.id}" class="tank-card nation-bg">
                            <img src="${basePath}${t.caminho_imagem}?v=${Date.now()}" alt="Silhueta" class="list-silhouette" onerror="this.src='${basePath}WT - Artes/WT-ICO2.ico'">
                            <div class="tank-info">
                                <span class="tank-name">${idx + 1}. ${t.nome}</span>
                                <span class="tank-desc">${t.descricao_breve ? t.descricao_breve : "Pendente."}</span>
                            </div>
                        </a>
                    `).join("");
                } else {
                    lista.innerHTML = '<div style="text-align: center; padding: 20px; color: #ff4d4d;">Nenhum veículo estacionado nesta base.</div>';
                }

                if (loading) loading.style.display = "none";
                container.style.display = "flex";

                if (role === "admin") {
                    if (btnEditar) {
                        btnEditar.style.display = "flex";
                        btnEditar.onclick = () => {
                            document.getElementById("editNacaoId").value = nacaoId;
                            document.getElementById("editNacaoNome").value = n.nome;
                            document.getElementById("editNacaoCor").value = n.cor_hex;
                            document.getElementById("editNacaoBandeira").value = n.caminho_bandeira || "";
                            document.getElementById("editNacaoLore").value = n.lore_taticas || "";
                            form.dataset.silhueta = n.icone_silhueta || "";
                            form.dataset.resumo = n.resumo_card || "";
                            modal.classList.add("ativo");
                        };
                    }
                    if (btnNovo) {
                        btnNovo.style.display = "flex";
                        btnNovo.onclick = async () => {
                            if (confirm("Autorizar início de produção de um novo blindado?")) {
                                btnNovo.innerHTML = "SOLICITANDO...";
                                btnNovo.disabled = true;
                                const fd = new FormData();
                                fd.append("acao", "novo_tanque");
                                fd.append("nacao_id", nacaoId);
                                const r = await apiTatica(`${basePath}php/api/admin_index_api.php`, fd);
                                if (r.ok && r.status === "success") {
                                    window.location.href = `${basePath}ficha.html?id=${r.novo_id}`;
                                } else {
                                    alert("Falha: " + r.message);
                                    btnNovo.disabled = false;
                                }
                            }
                        };
                    }
                }
            } else if (loading) {
                loading.innerHTML = `<span style='color:red;'>${res.message}</span>`;
            }
        } catch (err) {
            if (loading) loading.innerHTML = "<span style='color:red;'>Falha de conexão.</span>";
        }
    })();
}

function iniciarFicha(basePath) {
    const container = document.getElementById("fichaContainer");
    if (!container) return;

    const tankId = new URLSearchParams(window.location.search).get("id");
    const loading = document.getElementById("loadingOverlay");
    const modal = document.getElementById("edicaoTanqueModal");
    const btnAbrir = document.getElementById("btnAbrirEdicao");
    let atributos = [];
    let galeria = [];

    if (!tankId) {
        if (loading) loading.innerHTML = "<span style='color:red;'>ERRO: Blindado não especificado.</span>";
        return;
    }

    const coresClasse = { Leve: "#FFD700", "Médio": "#FF8C00", Pesado: "#DC143C", "Caça-Tanques": "#228B22", SPAA: "#8A2BE2" };
    const nomesClasse = { Leve: "Tanque Leve", "Médio": "Tanque Médio", Pesado: "Tanque Pesado", "Caça-Tanques": "Caça-Tanques", SPAA: "SPAA (Antiaérea)" };

    if (document.getElementById("closeEdicaoModal")) {
        document.getElementById("closeEdicaoModal").onclick = () => modal.classList.remove("ativo");
    }

    const resetAbas = () => {
        ["tabFichaLore", "tabGaleria"].forEach(id => {
            document.getElementById(id).style.background = "#333";
            document.getElementById(id).style.color = "#fff";
        });
        ["painelFichaLore", "painelGaleria"].forEach(id => {
            document.getElementById(id).style.display = "none";
        });
    };

    if (document.getElementById("tabFichaLore")) {
        document.getElementById("tabFichaLore").onclick = (e) => {
            resetAbas();
            e.target.style.background = "#F2B400";
            e.target.style.color = "#000";
            document.getElementById("painelFichaLore").style.display = "block";
        };
    }
    if (document.getElementById("tabGaleria")) {
        document.getElementById("tabGaleria").onclick = (e) => {
            resetAbas();
            e.target.style.background = "#F2B400";
            e.target.style.color = "#000";
            document.getElementById("painelGaleria").style.display = "block";
        };
    }

    higienizarCaminho("editCaminhoImagem");
    higienizarCaminho("novaFotoCaminho");

    const renderAtributos = () => {
        const box = document.getElementById("listaAtributosContainer");
        box.innerHTML = atributos.map((item, idx) => `
            <div class="attr-row">
                <div style="display:flex; flex-direction:column; gap:2px;">
                    <button type="button" class="btn-move btn-up" data-idx="${idx}">▲</button>
                    <button type="button" class="btn-move btn-down" data-idx="${idx}">▼</button>
                </div>
                <input type="text" class="input-chave" data-idx="${idx}" value="${item.chave}" style="flex: 1;" placeholder="Atributo">
                <input type="text" class="input-valor" data-idx="${idx}" value="${item.valor}" style="flex: 2;" placeholder="Valor">
                <button type="button" class="btn-del-attr" data-idx="${idx}" style="background:var(--rus-vermelho); color:#fff; border:none; padding:8px;">X</button>
            </div>
        `).join("");

        document.querySelectorAll(".input-chave").forEach(el => el.onchange = e => atributos[e.target.dataset.idx].chave = e.target.value);
        document.querySelectorAll(".input-valor").forEach(el => el.onchange = e => atributos[e.target.dataset.idx].valor = e.target.value);
        document.querySelectorAll(".btn-up").forEach(el => el.onclick = e => {
            const i = parseInt(e.target.dataset.idx);
            if (i > 0) { [atributos[i - 1], atributos[i]] = [atributos[i], atributos[i - 1]]; renderAtributos(); }
        });
        document.querySelectorAll(".btn-down").forEach(el => el.onclick = e => {
            const i = parseInt(e.target.dataset.idx);
            if (i < atributos.length - 1) { [atributos[i + 1], atributos[i]] = [atributos[i], atributos[i + 1]]; renderAtributos(); }
        });
        document.querySelectorAll(".btn-del-attr").forEach(el => el.onclick = e => {
            atributos.splice(parseInt(e.target.dataset.idx), 1);
            renderAtributos();
        });
    };

    if (document.getElementById("btnInjetarTemplate")) {
        document.getElementById("btnInjetarTemplate").onclick = () => {
            // Nova lista completa baseada na Ficha Técnica Avançada
            const templateAvancado = [
                "Classificação e BR",
                "Armamento Primário",
                "Armamento Secundário",
                "Cadência de Disparo",
                "Munição Principal",
                "Ângulos de Mira Vertical",
                "Velocidade de Rotação da Torre",
                "Blindagem Frontal (Glacis / Torre)",
                "Blindagem Lateral e Traseira",
                "Motor e Potência",
                "Relação Potência/Peso",
                "Velocidade Máxima",
                "Tripulação",
                "Custo de Pesquisa (RP)",
                "Custo de Compra (Silver Lions)"
            ];

            templateAvancado.forEach(ch => {
                // Só adiciona se a chave ainda não existir na lista de atributos
                if (!atributos.some(x => x.chave === ch)) {
                    atributos.push({ chave: ch, valor: "" });
                }
            });
            renderAtributos();
        };
    }

    if (document.getElementById("btnAdicionarAtributo")) {
        document.getElementById("btnAdicionarAtributo").onclick = () => {
            const ch = document.getElementById("novoAtributoChave").value.trim();
            const val = document.getElementById("novoAtributoValor").value.trim();
            if (ch) {
                atributos.push({ chave: ch, valor: val });
                document.getElementById("novoAtributoChave").value = "";
                document.getElementById("novoAtributoValor").value = "";
                renderAtributos();
            }
        };
    }

    const renderGaleria = () => {
        const box = document.getElementById("listaGaleriaContainer");
        box.innerHTML = galeria.map((img, idx) => `
            <div style="display:flex; justify-content:space-between; align-items:center; background:#222; padding:8px; border:1px solid #444; border-radius:3px;">
                <div style="font-size:11px; color:#aaa;"><strong style="color:#F2B400;">${img.legenda}</strong><br>${img.url}</div>
                <button type="button" class="btn-del-img" data-index="${idx}" style="background:var(--rus-vermelho); color:#fff; padding:4px 8px; border:none;">X</button>
            </div>
        `).join("");
        document.querySelectorAll(".btn-del-img").forEach(el => el.onclick = e => {
            galeria.splice(parseInt(e.target.dataset.index), 1);
            renderGaleria();
        });
    };

    if (document.getElementById("btnAdicionarFoto")) {
        document.getElementById("btnAdicionarFoto").onclick = () => {
            const url = document.getElementById("novaFotoCaminho").value.trim();
            const leg = document.getElementById("novaFotoLegenda").value.trim();
            if (url) {
                galeria.push({ url, legenda: leg || "Visão Oficial em Combate" });
                document.getElementById("novaFotoCaminho").value = "";
                document.getElementById("novaFotoLegenda").value = "";
                renderGaleria();
            }
        };
    }

    if (document.getElementById("formEdicaoTanque")) {
        document.getElementById("formEdicaoTanque").onsubmit = async (e) => {
            e.preventDefault();
            const btn = document.getElementById("btnSalvarDossie");
            btn.disabled = true;
            btn.innerHTML = "SALVANDO...";
            try {
                const fd = new FormData();
                fd.append("id", document.getElementById("editTankId").value);
                fd.append("nome", document.getElementById("editNomePrincipal").value);
                fd.append("descricao_breve", document.getElementById("editDescricaoBreve").value);
                fd.append("caminho_imagem", document.getElementById("editCaminhoImagem").value);

                const acharVal = (c) => { const item = atributos.find(x => x.chave === c); return item ? item.valor : ""; };
                fd.append("armamento", acharVal("Armamento Principal"));
                fd.append("velocidade", acharVal("Velocidade Máxima"));
                fd.append("blindagem_chassi", acharVal("Blindagem do Chassi"));
                fd.append("blindagem_torre", acharVal("Blindagem da Torre"));
                fd.append("historico", document.getElementById("editHistorico").value);
                fd.append("taticas", document.getElementById("editTaticas").value);
                fd.append("detalhes_extras", JSON.stringify(atributos));
                fd.append("galeria_imagens", JSON.stringify(galeria));
                fd.append("classe_veiculo", document.getElementById("editClasse").value);
                fd.append("tipo", document.getElementById("editFuncao").value);
                fd.append("nivel", document.getElementById("editNivel").value);
                fd.append("nacao_id", document.getElementById("editNacaoId").value);

                const r = await apiTatica(`${basePath}php/api/atualizar_ficha.php`, fd);
                if (r.ok) window.location.reload();
            } catch (err) {
                btn.disabled = false;
                btn.innerHTML = "ERRO";
            }
        };
    }

    const btnExcluir = document.getElementById("btnExcluirDossie");
    if (btnExcluir) {
        btnExcluir.onclick = async () => {
            if (confirm("ALERTA CRÍTICO: Tem certeza que deseja DELETAR o tanque?")) {
                btnExcluir.disabled = true;
                btnExcluir.innerHTML = "INCINERANDO...";
                const fd = new FormData();
                fd.append("id", document.getElementById("editTankId").value);
                const r = await apiTatica(`${basePath}php/api/excluir_tanque.php`, fd);
                if (r.ok) window.location.href = `${basePath}index.html`;
            }
        };
    }

    (async () => {
        try {
            const res = await apiTatica(`${basePath}php/api/ficha_api.php?id=${tankId}`);
            if (res.status === "success") {
                const d = res.dados;
                document.title = `${d.nome} - Ficha Tática`;
                document.getElementById("dinNomeTanque").textContent = d.nome;

                const cl = d.classe_veiculo || "Médio";
                let badgeTxt = nomesClasse[cl] || cl;
                if (d.tipo && d.tipo.trim() !== "") badgeTxt += ` (${d.tipo})`;
                badgeTxt += ` | ${d.nivel || "Nível ?"}`;

                const badgeEl = document.getElementById("dinTipoNivel");
                badgeEl.textContent = badgeTxt;
                badgeEl.style.backgroundColor = coresClasse[cl] || "#1A3668";
                badgeEl.style.color = cl === "Leve" ? "#000000" : "#ffffff";

                document.getElementById("dinHistorico").innerHTML = d.historico ? formatarTextoTatico(d.historico) : "<p>Histórico classificado.</p>";
                document.getElementById("dinTaticas").innerHTML = d.taticas ? formatarTextoTatico(d.taticas) : "<p>Doutrina em formulação.</p>";

                if (d.detalhes_extras && d.detalhes_extras !== "{}") {
                    try {
                        const parsed = JSON.parse(d.detalhes_extras);
                        atributos = Array.isArray(parsed) ? parsed : Object.entries(parsed).map(([chave, valor]) => ({ chave, valor }));
                    } catch (e) {}
                }

                [
                    { chave: "Armamento Principal", val: d.armamento },
                    { chave: "Blindagem do Chassi", val: d.blindagem_chassi },
                    { chave: "Blindagem da Torre", val: d.blindagem_torre },
                    { chave: "Velocidade Máxima", val: d.velocidade }
                ].forEach(x => {
                    if (!atributos.some(a => a.chave === x.chave) && x.val) {
                        atributos.push({ chave: x.chave, valor: x.val });
                    }
                });

                const tbodySpec = document.getElementById("tabelaEspecificacoesBody");
                tbodySpec.innerHTML = atributos
                    .filter(a => a.valor && a.valor.trim() !== "")
                    .map(a => `<tr><th>${a.chave}</th><td>${a.valor}</td></tr>`)
                    .join("");

                const track = document.getElementById("tank-track");
                const caption = document.getElementById("tank-caption");
                const btnPrev = document.getElementById("btnPrev");
                const btnNext = document.getElementById("btnNext");

                if (d.galeria_imagens) {
                    try { galeria = JSON.parse(d.galeria_imagens); } catch (e) {}
                }

                if (galeria.length > 0) {
                    track.innerHTML = galeria.map(img => `<img src="${basePath}${img.url}?v=${Date.now()}" alt="${img.legenda}" class="slide-item">`).join("");
                    caption.textContent = galeria[0].legenda || "Visão Oficial em Combate";
                    if (galeria.length > 1) {
                        btnPrev.style.display = "block";
                        btnNext.style.display = "block";
                        let idx = 0;
                        const mover = () => {
                            track.style.transform = `translateX(-${100 * idx}%)`;
                            caption.textContent = galeria[idx].legenda || "";
                        };
                        btnNext.onclick = () => { idx = (idx + 1) % galeria.length; mover(); };
                        btnPrev.onclick = () => { idx = (idx - 1 + galeria.length) % galeria.length; mover(); };
                    }
                } else {
                    const imgFallback = (d.caminho_imagem || "").replace("shadow.svg", "foto.webp").replace("shadow.png", "foto.webp");
                    document.getElementById("dinImagemPrincipal").src = `${basePath}${imgFallback}?v=${Date.now()}`;
                }

                if (loading) loading.style.display = "none";
                container.style.display = "block";

                if ((localStorage.getItem("userRole") || "").toLowerCase() === "admin" && btnAbrir) {
                    btnAbrir.style.display = "flex";
                    btnAbrir.onclick = async () => {
                        const selNacao = document.getElementById("editNacaoId");
                        if (selNacao) {
                            try {
                                const rn = await apiTatica(`${basePath}php/api/listar_nacoes.php`);
                                if (rn.status === "success") {
                                    selNacao.innerHTML = rn.nacoes.map(n => `<option value="${n.Id}">${n.nome}</option>`).join("");
                                }
                            } catch (e) {}
                        }
                        document.getElementById("editTankId").value = d.id;
                        document.getElementById("editNomePrincipal").value = d.nome || "";
                        document.getElementById("editDescricaoBreve").value = d.descricao_breve || "";
                        document.getElementById("editCaminhoImagem").value = d.caminho_imagem || "";
                        document.getElementById("editNomeTitulo").textContent = d.nome;
                        document.getElementById("editHistorico").value = d.historico || "";
                        document.getElementById("editTaticas").value = d.taticas || "";
                        document.getElementById("editClasse").value = d.classe_veiculo || "Médio";
                        document.getElementById("editFuncao").value = d.tipo || "";
                        document.getElementById("editNivel").value = d.nivel || "I";
                        if (selNacao) selNacao.value = d.nacao_id || "1";
                        renderAtributos();
                        renderGaleria();
                        modal.classList.add("ativo");
                    };
                }
            }
        } catch (err) {
            if (loading) loading.innerHTML = "<span style='color:red;'>FALHA CRÍTICA DE CONEXÃO.</span>";
        }
    })();
}

/**
 * 8. UTILITÁRIOS DE VISUALIZAÇÃO E CONFIGURAÇÕES (Botão de Eficiência Curto e Sem Animação)
 */
function iniciarScrollSuave() {
    const btn = document.getElementById("btnVoltarTopo");
    if (!btn) return;
    window.addEventListener("scroll", () => {
        btn.classList.toggle("visivel", window.scrollY > 300);
    });
    btn.addEventListener("click", () => {
        document.body.scrollIntoView({ behavior: "smooth", block: "start" });
    });
}

function iniciarToggleVisualizacao() {
    const btn = document.getElementById("btnToggleView");
    const content = document.querySelector(".nation-content");
    if (btn && content) {
        btn.addEventListener("click", () => {
            content.classList.toggle("list-view");
            btn.innerHTML = content.classList.contains("list-view") ? "&#9638; MODO CAIXAS" : "&#9776; MODO LISTA";
        });
    }
}

function iniciarConfig() {
    const modal = document.getElementById("configModal");
    const btnOpen = document.getElementById("btnOpenConfig");
    const btnClose = document.getElementById("closeConfigModal");
    const chkPerf = document.getElementById("togglePerf");
    const btnPerf = document.getElementById("btnPerfToggle");
    const themeSelect = document.getElementById("themeSelect");
    const langSelect = document.getElementById("langSelect");
    const btnPurge = document.getElementById("btnPurge");

    if (!modal || !btnOpen) return;

    btnOpen.addEventListener("click", (e) => {
        e.preventDefault();
        modal.classList.add("ativo");
    });
    btnClose.addEventListener("click", () => modal.classList.remove("ativo"));

    // Botão Curto e Sem Animação para Desempenho Extremo
    const aplicarEstadoPerf = (ativo) => {
        chkPerf.checked = ativo;
        document.body.classList.toggle("low-perf", ativo);
        if (btnPerf) {
            btnPerf.setAttribute("aria-checked", ativo ? "true" : "false");
            btnPerf.textContent = ativo ? "ATIVO" : "OFF";
            btnPerf.style.background = ativo ? "var(--rus-vermelho)" : "#2A2D2E";
            btnPerf.style.borderColor = ativo ? "#ff4d4d" : "#8a8d8f";
            btnPerf.style.color = ativo ? "#fff" : "#aaa";
        }
    };

    aplicarEstadoPerf(localStorage.getItem("lowPerf") === "true");

    if (btnPerf) {
        btnPerf.addEventListener("click", () => {
            const novoEstado = !chkPerf.checked;
            localStorage.setItem("lowPerf", novoEstado ? "true" : "false");
            aplicarEstadoPerf(novoEstado);
        });
    }

    // Temas
    const tema = localStorage.getItem("siteTheme") || "dark";
    themeSelect.value = tema;
    if (tema === "desert") document.body.classList.add("theme-desert");
    if (tema === "night") document.body.classList.add("theme-night");

    themeSelect.addEventListener("change", (e) => {
        document.body.classList.remove("theme-desert", "theme-night");
        if (e.target.value === "desert") document.body.classList.add("theme-desert");
        if (e.target.value === "night") document.body.classList.add("theme-night");
        localStorage.setItem("siteTheme", e.target.value);
    });

    // Idioma
    langSelect.value = localStorage.getItem("siteLang") || "pt";
    langSelect.addEventListener("change", (e) => {
        localStorage.setItem("siteLang", e.target.value);
        const banner = document.getElementById("customBanner");
        if (banner) {
            document.getElementById("customBannerText").textContent = "Idioma salvo. Atualize a página.";
            document.getElementById("bannerIcon").innerHTML = "language";
            banner.classList.add("show");
            setTimeout(() => banner.classList.remove("show"), 4000);
        }
    });

    btnPurge.addEventListener("click", () => {
        localStorage.clear();
        location.reload();
    });
}

/**
 * 9. ORQUESTRADOR PRINCIPAL (BOOTSTRAP DO FRONTEND)
 */
function injetarMenu(basePath) {
    document.addEventListener("DOMContentLoaded", () => {
        injetarInterface(basePath);
        iniciarLogin(basePath);
        iniciarRegistro(basePath);
        iniciarRecuperacaoSenha(basePath);
        iniciarPerfil(basePath);
        iniciarConfig();
        iniciarRelogio();
        ativarRadarPesquisa(basePath);
        ativarAbaTatica();
        iniciarScrollSuave();
        iniciarToggleVisualizacao();
        iniciarTropas(basePath);
        iniciarIndex(basePath);
        iniciarNacao(basePath);
        iniciarFicha(basePath);
        sincronizarSessaoServidor(basePath);
        iniciarExpansaoWiki(basePath);

        // Monta o seletor de Nação Favorita no topo (com SVG oficial + Nações do Banco)
        apiTatica(`${basePath}php/api/listar_nacoes.php`).then(res => {
            if (res.status === "success" && res.nacoes) {
                window.NACOES_BANCO_CACHE = res.nacoes;
            }
            const dropdownLista = document.getElementById("listaDinamicaNacoesDropdown");
            renderizarPlacaNacaoTopo(obterNacaoFavoritaCliente(), basePath);

            if (dropdownLista) {
                const opcoesPadrao = Object.values(NACOES_CONFIG);
                dropdownLista.innerHTML = opcoesPadrao.map(nac => `
                    <div class="nation-opt" data-nacao="${nac.sigla}" style="display:flex;align-items:center;gap:10px;padding:8px 12px;cursor:pointer;border-bottom:1px solid #222;font-size:11px;color:#fff;" onmouseover="this.style.background='#252525'" onmouseout="this.style.background='transparent'">
                        ${nac.svg}
                        <span><strong>${nac.sigla}</strong> – ${nac.nome}</span>
                    </div>
                `).join("");

                dropdownLista.querySelectorAll(".nation-opt").forEach(opt => {
                    opt.addEventListener("click", async (ev) => {
                        ev.stopPropagation();
                        const siglaEscolhida = opt.getAttribute("data-nacao");
                        definirNacaoFavoritaCliente(siglaEscolhida);
                        renderizarPlacaNacaoTopo(siglaEscolhida, basePath);
                        document.getElementById("userNationDropdown").style.display = "none";

                        if (localStorage.getItem("isAuth") === "true") {
                            try {
                                const fd = new FormData();
                                fd.append("acao", "salvar_nacao");
                                fd.append("nacao", siglaEscolhida);
                                await apiTatica(`${basePath}php/api/usuarios.php`, fd);
                            } catch (err) {
                                console.error("Erro ao vincular nação:", err);
                            }
                        }
                    });
                });
            }
        }).catch(() => {});

        // Fechamento global de menus dropdown ao clicar fora
        document.addEventListener("click", (ev) => {
            const btnMenu = document.getElementById("navToggleBtn");
            const navbar = document.querySelector(".top-navbar");
            if (btnMenu && navbar) {
                if (btnMenu.contains(ev.target)) {
                    navbar.classList.toggle("expanded");
                } else if (!navbar.contains(ev.target)) {
                    navbar.classList.remove("expanded");
                }
            }

            const badge = document.getElementById("userNationBadge");
            const drop = document.getElementById("userNationDropdown");
            if (badge && drop) {
                if (badge.contains(ev.target)) {
                    drop.style.display = drop.style.display === "block" ? "none" : "block";
                } else {
                    drop.style.display = "none";
                }
            }
        });
    });
}

/**
 * ============================================================================
 * 10. EXPANSÃO WIKI 2.0 (COMENTÁRIOS, LIKES/RESPOSTAS, COMPARADOR E SHARE)
 * ============================================================================
 */
function iniciarExpansaoWiki(basePath) {
    // 1. Injeta o Botão "COMPARAR" na Navbar e o Modal de Telemetria Cruzada
    const navRight = document.querySelector(".nav-right");
    const btnConfig = document.getElementById("btnOpenConfig");
    if (navRight && !document.getElementById("btnOpenComparador")) {
        const itemComp = document.createElement("a");
        itemComp.href = "#";
        itemComp.className = "nav-item";
        itemComp.id = "btnOpenComparador";
        itemComp.innerHTML = `
            <div class="icon-box"><span class="material-symbols-outlined" style="font-size:32px; color:#F2B400;">compare_arrows</span></div>
            <div class="text-box">COMPARAR</div>
        `;
        navRight.insertBefore(itemComp, btnConfig);
    }

    const htmlModalComparador = `
    <div class="modal-overlay" id="comparadorModal">
        <div class="modal-box" style="max-width: 920px;">
            <button class="fechar-modal" id="closeComparadorModal">X</button>
            <h2 class="modal-title">TELEMETRIA CRUZADA</h2>
            <p class="modal-subtitle">Comparação Tática Lado a Lado de Blindados</p>

            <div class="comp-selectors-row">
                <div class="comp-tank-box">
                    <label style="display:block; color:#F2B400; font-size:11px; font-weight:bold; margin-bottom:8px;">BLINDADO ALFA (ESQUERDA)</label>
                    <select id="selectCompAlfa" style="width:100%; padding:8px; background:#111; color:#fff; border:1px solid #555; border-radius:4px; font-family:monospace;"></select>
                    <div id="previewCompAlfa" style="margin-top:12px;"></div>
                </div>
                <div class="comp-tank-box">
                    <label style="display:block; color:#F2B400; font-size:11px; font-weight:bold; margin-bottom:8px;">BLINDADO BRAVO (DIREITA)</label>
                    <select id="selectCompBravo" style="width:100%; padding:8px; background:#111; color:#fff; border:1px solid #555; border-radius:4px; font-family:monospace;"></select>
                    <div id="previewCompBravo" style="margin-top:12px;"></div>
                </div>
            </div>

            <div class="modal-body-scroll" style="max-height: 45vh; border:1px solid #2a2a2a; border-radius:6px; background:#0e1011;">
                <table class="comp-table">
                    <thead>
                        <tr>
                            <th id="thCompAlfa" style="text-align:right;">BLINDADO ALFA</th>
                            <th>ATRIBUTO TÁTICO</th>
                            <th id="thCompBravo" style="text-align:left;">BLINDADO BRAVO</th>
                        </tr>
                    </thead>
                    <tbody id="tbodyComparador"></tbody>
                </table>
            </div>
        </div>
    </div>`;
    document.body.insertAdjacentHTML("beforeend", htmlModalComparador);

    const modalComp = document.getElementById("comparadorModal");
    const btnOpenComp = document.getElementById("btnOpenComparador");
    const btnCloseComp = document.getElementById("closeComparadorModal");
    const selAlfa = document.getElementById("selectCompAlfa");
    const selBravo = document.getElementById("selectCompBravo");

    if (btnCloseComp) btnCloseComp.onclick = () => modalComp.classList.remove("ativo");

    // Extrai o primeiro número de uma string (ex: "200 mm (inclinada)" -> 200) para destacar o vencedor
    // Extração inteligente que lida com ângulos negativos e contagem de armamentos
    const extrairNumero = (str, chaveAtributo = "") => {
        if (!str) return null;
        const texto = String(str).toLowerCase();

        // 1. Exceção para Ângulos de Mira Vertical (Ex: "-3° / +20°" ou "-10° / +20°")
        // O melhor ângulo de depressão é o mais negativo (ex: -10° alcança mais terreno que -3°)
        if (chaveAtributo.toLowerCase().includes("ângulo") || chaveAtributo.toLowerCase().includes("depressão")) {
            const matches = texto.match(/-?\d+/g);
            if (matches && matches.length > 0) {
                return parseFloat(matches[0]); // Pega o primeiro número (a depressão máxima, ex: -10 é menor que -3, logo ganha)
            }
        }

        // 2. Extração Padrão de Números
        const m = texto.replace(",", ".").match(/-?\d+(\.\d+)?/);
        return m ? parseFloat(m[0]) : null;
    };

    const obterMapaAtributos = (tanque) => {
        const mapa = {
            "Nação": tanque.nacao_nome || "--",
            "Classe / Função": `${tanque.classe_veiculo || "Tanque"} (${tanque.tipo || "Padrão"})`,
            "Nível": tanque.nivel || "--",
            "Armamento Principal": tanque.armamento || "--",
            "Blindagem do Chassi": tanque.blindagem_chassi || "--",
            "Blindagem da Torre": tanque.blindagem_torre || "--",
            "Velocidade Máxima": tanque.velocidade || "--"
        };
        if (tanque.detalhes_extras && tanque.detalhes_extras !== "{}") {
            try {
                const parsed = JSON.parse(tanque.detalhes_extras);
                const lista = Array.isArray(parsed) ? parsed : Object.entries(parsed).map(([chave, valor]) => ({ chave, valor }));
                lista.forEach(item => {
                    if (item.chave && item.valor && item.valor.trim() !== "") {
                        mapa[item.chave] = item.valor;
                    }
                });
            } catch (e) {}
        }
        return mapa;
    };

    const renderizarComparacao = () => {
        const lista = window.CATALOGO_TANQUES_WIKI || [];
        const tA = lista.find(x => String(x.id) === String(selAlfa.value));
        const tB = lista.find(x => String(x.id) === String(selBravo.value));
        if (!tA || !tB) return;

        document.getElementById("thCompAlfa").textContent = tA.nome.toUpperCase();
        document.getElementById("thCompBravo").textContent = tB.nome.toUpperCase();

        const renderPreview = (t) => `
            <img src="${basePath}${t.caminho_imagem}?v=${Date.now()}" style="height:65px; object-fit:contain; filter:brightness(0) drop-shadow(0 0 2px #fff);" onerror="this.src='${basePath}WT - Artes/WT-ICO2.ico'">
            <div style="font-size:12px; color:#ccc; margin-top:4px;">${t.nacao_nome || ""} • Nível ${t.nivel || "?"}</div>
            <a href="${basePath}ficha.html?id=${t.id}" style="display:inline-block; margin-top:6px; font-size:10px; color:#F2B400; font-weight:bold;">ABRIR DOSSIÊ ▶</a>
        `;
        document.getElementById("previewCompAlfa").innerHTML = renderPreview(tA);
        document.getElementById("previewCompBravo").innerHTML = renderPreview(tB);

        const mapaA = obterMapaAtributos(tA);
        const mapaB = obterMapaAtributos(tB);
        const todasChaves = Array.from(new Set([...Object.keys(mapaA), ...Object.keys(mapaB)]));

        const tbody = document.getElementById("tbodyComparador");
        tbody.innerHTML = todasChaves.map(chave => {
            const valA = mapaA[chave] || "--";
            const valB = mapaB[chave] || "--";

            // Compara numericamente atributos de performance (Blindagem, Velocidade, Armamento, Potência)
            let classA = "comp-val-left";
            let classB = "comp-val-right";
            let setaA = "";
            let setaB = "";

            const chaveLower = chave.toLowerCase();
            const ehMetralhadora = chaveLower.includes("metralhadora") || chaveLower.includes("secundário");
            const ehAngulo = chaveLower.includes("ângulo") || chaveLower.includes("depressão");
            const ehVelocidadeTorre = chaveLower.includes("rotação da torre") || chaveLower.includes("arco horizontal");

            if (!["nação", "classe / função", "nível", "custo de pesquisa (rp)", "custo de compra (silver lions)"].includes(chaveLower)) {
                
                // Tratamento especial para Contagem de Armamento / Metralhadoras (Ex: "1x 12.7mm + 2x 7.62mm" = 3 armas vs Nenhuma)
                if (ehMetralhadora) {
                    const totalArmasA = (valA.match(/\d+x/g) || []).reduce((acc, cur) => acc + parseInt(cur), 0) || (valA.toLowerCase().includes("nenhum") ? 0 : 1);
                    const totalArmasB = (valB.match(/\d+x/g) || []).reduce((acc, cur) => acc + parseInt(cur), 0) || (valB.toLowerCase().includes("nenhum") ? 0 : 1);
                    
                    if (totalArmasA !== totalArmasB) {
                        if (totalArmasA > totalArmasB) { classA += " comp-winner"; setaA = "▲ "; }
                        else { classB += " comp-winner"; setaB = " ▲"; }
                    }
                } else {
                    // Tratamento numérico padrão com suporte a ângulos e rotações
                    const numA = extrairNumero(valA, chave);
                    const numB = extrairNumero(valB, chave);

                    if (numA !== null && numB !== null && numA !== numB) {
                        let aVence = false;
                        const menorEhMelhor = chaveLower.includes("cadência") || chaveLower.includes("recarga");

                        if (ehAngulo) {
                            // Para depressão, quanto mais negativo, maior a amplitude (ex: -10° é melhor que -3°)
                            aVence = numA < numB; 
                        } else if (ehVelocidadeTorre && valA.toLowerCase().includes("fixo") || valB.toLowerCase().includes("fixo")) {
                            // Torre com arco fixo (caça-tanques) perde em mobilidade de mira para torre livre de 40°/s
                            aVence = !valA.toLowerCase().includes("fixo");
                        } else {
                            aVence = menorEhMelhor ? (numA < numB) : (numA > numB);
                        }

                        if (aVence) {
                            classA += " comp-winner";
                            setaA = "▲ ";
                        } else {
                            classB += " comp-winner";
                            setaB = " ▲";
                        }
                    }
                }
            }

            return `
                <tr>
                    <td class="${classA}">${setaA}${valA}</td>
                    <th style="font-weight:bold;">${chave}</th>
                    <td class="${classB}">${valB}${setaB}</td>
                </tr>
            `;
        }).join("");
    };

    const abrirModalComparador = (idPreSelecionado = null) => {
        const lista = window.CATALOGO_TANQUES_WIKI || [];
        if (lista.length === 0) return;

        const opcoesHtml = lista.map(t => `<option value="${t.id}">[${t.nacao_nome || "WT"}] ${t.nome}</option>`).join("");
        selAlfa.innerHTML = opcoesHtml;
        selBravo.innerHTML = opcoesHtml;

        if (idPreSelecionado && lista.some(x => String(x.id) === String(idPreSelecionado))) {
            selAlfa.value = idPreSelecionado;
        } else {
            selAlfa.value = lista[0].id;
        }
        selBravo.value = lista.length > 1 ? (String(lista[1].id) === String(selAlfa.value) ? lista[0].id : lista[1].id) : lista[0].id;

        renderizarComparacao();
        modalComp.classList.add("ativo");
    };

    if (btnOpenComp) {
        btnOpenComp.addEventListener("click", (e) => {
            e.preventDefault();
            const tankIdPagina = new URLSearchParams(window.location.search).get("id");
            abrirModalComparador(tankIdPagina);
        });
    }
    selAlfa.addEventListener("change", renderizarComparacao);
    selBravo.addEventListener("change", renderizarComparacao);

    // 2. Carrega o Catálogo da Wiki (Alimenta o Comparador + Hiperlinks da Lore)
    apiTatica(`${basePath}php/api/comunidade_wiki.php?acao=catalogo_wiki`).then(res => {
        if (res.status === "success" && res.tanques) {
            window.CATALOGO_TANQUES_WIKI = res.tanques;
            // Re-aplica os hiperlinks caso a lore já esteja carregada na tela
            ["dinHistorico", "dinTaticas", "dinLoreNacao"].forEach(idEl => {
                const el = document.getElementById(idEl);
                if (el && el.innerHTML && !el.innerHTML.includes("wiki-inline-link")) {
                    el.innerHTML = formatarTextoTatico(el.innerHTML, basePath);
                }
            });
        }
    }).catch(() => {});

    // 3. Se estivermos na página de Ficha Tática (ficha.html), ativa Compartilhamento, Open Graph e Comentários
    const fichaContainer = document.getElementById("fichaContainer");
    const tankId = new URLSearchParams(window.location.search).get("id");
    if (!fichaContainer || !tankId) return;

    // 3.1 Botões "COMPARTILHAR DOSSIÊ" e "COMPARAR BLINDADO" na Barra Superior da Ficha
    const topBar = document.querySelector(".top-bar-controls");
    if (topBar) {
        const divAcoesExtras = document.createElement("div");
        divAcoesExtras.style = "display:flex; gap:8px; flex-wrap:wrap;";
        divAcoesExtras.innerHTML = `
            <button type="button" id="btnCompararEsteTanque" class="btn-submit-militar btn-militar-auto btn-militar-blue" style="padding:8px 14px;">
                <span class="material-symbols-outlined" style="font-size:16px;">compare_arrows</span> COMPARAR
            </button>
            <button type="button" id="btnCompartilharDossie" class="btn-submit-militar btn-militar-auto" style="background:#2A2D2E; color:#F2B400; border-color:#F2B400; padding:8px 14px;">
                <span class="material-symbols-outlined" style="font-size:16px;">share</span> COMPARTILHAR DOSSIÊ
            </button>
        `;
        topBar.appendChild(divAcoesExtras);

        document.getElementById("btnCompararEsteTanque").onclick = () => abrirModalComparador(tankId);
        document.getElementById("btnCompartilharDossie").onclick = async () => {
            const urlShare = `${window.location.origin}${window.location.pathname.replace("ficha.html", "")}php/compartilhar.php?id=${tankId}`;
            try {
                await navigator.clipboard.writeText(urlShare);
                const banner = document.getElementById("customBanner");
                if (banner) {
                    document.getElementById("customBannerText").textContent = "Link Tático (com Preview p/ Discord e WhatsApp) copiado!";
                    document.getElementById("bannerIcon").innerHTML = "share";
                    banner.classList.add("show");
                    setTimeout(() => banner.classList.remove("show"), 4000);
                }
            } catch (e) {
                prompt("Copie o link tático de compartilhamento:", urlShare);
            }
        };
    }

    // 3.2 Injeta a Seção de Relatórios de Combate (Comentários, Respostas e Likes/Dislikes)
    const secaoComentarios = document.createElement("section");
    secaoComentarios.className = "combat-reports-section";
    secaoComentarios.innerHTML = `
        <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:2px solid var(--dourado-titulos); padding-bottom:12px; margin-bottom:20px; flex-wrap:wrap; gap:10px;">
            <div>
                <h2 style="color:var(--dourado-titulos); font-size:20px; letter-spacing:1px; margin:0;">RELATÓRIOS DE COMBATE DA COMUNIDADE</h2>
                <p style="color:#888; font-size:12px; margin-top:4px;">Dicas táticas de comandantes, análises de blindagem e contra-medidas</p>
            </div>
            <span id="badgeTotalComentarios" style="background:#111; border:1px solid #444; color:#F2B400; padding:5px 12px; border-radius:20px; font-family:monospace; font-size:12px; font-weight:bold;">0 RELATÓRIOS</span>
        </div>

        <div id="boxFormularioComentario" style="margin-bottom:25px;"></div>
        <div id="comentarioFeedback" class="tactical-feedback"></div>
        <div id="listaComentariosContainer">
            <div style="text-align:center; padding:20px; color:#F2B400; font-family:monospace;">Sincronizando transmissões de rádio...</div>
        </div>
    `;
    fichaContainer.insertAdjacentElement("afterend", secaoComentarios);

    const boxForm = document.getElementById("boxFormularioComentario");
    const listaComEl = document.getElementById("listaComentariosContainer");
    const feedbackCom = document.getElementById("comentarioFeedback");
    const badgeTotal = document.getElementById("badgeTotalComentarios");

    const mostrarAvisoComentario = (msg, ok = true) => {
        feedbackCom.style.display = "block";
        feedbackCom.className = `tactical-feedback ${ok ? "feedback-success" : "feedback-error"}`;
        feedbackCom.textContent = msg;
        setTimeout(() => { feedbackCom.style.display = "none"; }, 4000);
    };

    const montarCaixaEnvio = () => {
        if (localStorage.getItem("isAuth") === "true") {
            boxForm.innerHTML = `
                <form id="formNovoComentario" style="background:#141617; padding:15px; border:1px solid #333; border-radius:6px;">
                    <label style="display:block; color:#F2B400; font-size:11px; font-family:monospace; font-weight:bold; margin-bottom:8px;">
                        TRANSMITIR NOVO RELATÓRIO TÁTICO COMO [${(localStorage.getItem("userNickname") || "SOLDADO").toUpperCase()}]
                    </label>
                    <textarea id="inputTextoComentario" rows="3" maxlength="1000" required
                              placeholder="Compartilhe uma dica de angulação, munição recomendada ou ponto fraco deste blindado..."
                              style="width:100%; padding:10px; background:#0d0e0f; color:#fff; border:1px solid #444; border-radius:4px; font-family:Arial, sans-serif; font-size:13px; resize:vertical;"></textarea>
                    <div style="display:flex; justify-content:flex-end; margin-top:10px;">
                        <button type="submit" id="btnEnviarComentario" class="btn-submit-militar btn-militar-auto btn-militar-gold" style="padding:8px 18px;">
                            TRANSMITIR RELATÓRIO
                        </button>
                    </div>
                </form>
            `;
            document.getElementById("formNovoComentario").addEventListener("submit", async (e) => {
                e.preventDefault();
                const txt = document.getElementById("inputTextoComentario").value.trim();
                if (!txt) return;
                const btn = document.getElementById("btnEnviarComentario");
                btn.disabled = true;
                btn.textContent = "TRANSMITINDO...";

                const fd = new FormData();
                fd.append("acao", "publicar_comentario");
                fd.append("tanque_id", tankId);
                fd.append("conteudo", txt);

                try {
                    const res = await apiTatica(`${basePath}php/api/comunidade_wiki.php`, fd);
                    mostrarAvisoComentario(res.message, res.status === "success");
                    if (res.status === "success") {
                        document.getElementById("inputTextoComentario").value = "";
                        carregarComentarios();
                    }
                } catch (err) {
                    mostrarAvisoComentario("Falha de transmissão.", false);
                }
                btn.disabled = false;
                btn.textContent = "TRANSMITIR RELATÓRIO";
            });
        } else {
            boxForm.innerHTML = `
                <div style="background:#141617; border:1px dashed #444; padding:15px; border-radius:6px; text-align:center; color:#aaa; font-size:13px;">
                    Identificação necessária para enviar relatórios, responder ou avaliar dicas. 
                    <a href="#" id="linkLoginComentario" style="color:#F2B400; font-weight:bold; margin-left:6px; text-decoration:underline;">AUTENTICAR AGORA</a>
                </div>
            `;
            const linkLog = document.getElementById("linkLoginComentario");
            if (linkLog) {
                linkLog.onclick = (e) => {
                    e.preventDefault();
                    document.getElementById("loginModal").classList.add("ativo");
                };
            }
        }
    };

    const renderizarCardItem = (item, ehResposta = false) => {
        const isAdm = (item.perfil || "").toLowerCase() === "admin";
        const nacaoObj = resolverNacao(item.nacao_favorita, basePath);
        const badgePatente = isAdm
            ? '<span style="background:#F2B400; color:#000; padding:2px 6px; border-radius:3px; font-size:9px; font-weight:bold;">ALTO COMANDO</span>'
            : '<span style="background:#333; color:#ccc; padding:2px 6px; border-radius:3px; font-size:9px; font-weight:bold;">SOLDADO</span>';

        const classeLike = item.meu_voto === 1 ? "voted-like" : "";
        const classeDislike = item.meu_voto === -1 ? "voted-dislike" : "";

        const btnResponderHtml = (!ehResposta && localStorage.getItem("isAuth") === "true")
            ? `<button type="button" class="btn-vote-tactical" onclick="window.abrirCaixaResposta(${item.id})">💬 RESPONDER</button>`
            : "";

        const btnExcluirHtml = item.pode_excluir
            ? `<button type="button" class="btn-vote-tactical" style="border-color:#6E1111; color:#ff8080; margin-left:auto;" onclick="window.excluirComentarioWiki(${item.id})">🗑 EXCLUIR</button>`
            : "";

        const respostasFilhasHtml = (!ehResposta && item.respostas && item.respostas.length > 0)
            ? `<div class="replies-container">${item.respostas.map(r => renderizarCardItem(r, true)).join("")}</div>`
            : "";

        const caixaRespostaHtml = !ehResposta ? `
            <div id="boxResposta_${item.id}" style="display:none; margin-top:12px; padding-top:10px; border-top:1px dashed #333;">
                <textarea id="inputResposta_${item.id}" rows="2" maxlength="1000" placeholder="Escreva sua resposta para ${item.nickname}..."
                          style="width:100%; padding:8px; background:#0b0c0d; color:#fff; border:1px solid #444; border-radius:4px; font-size:12px;"></textarea>
                <div style="display:flex; justify-content:flex-end; gap:8px; margin-top:6px;">
                    <button type="button" class="btn-vote-tactical" onclick="document.getElementById('boxResposta_${item.id}').style.display='none'">CANCELAR</button>
                    <button type="button" class="btn-vote-tactical" style="background:#F2B400; color:#000; border-color:#F2B400;" onclick="window.enviarRespostaWiki(${item.id})">ENVIAR RESPOSTA</button>
                </div>
            </div>
        ` : "";

        return `
            <div class="${ehResposta ? "reply-card" : `comment-card ${isAdm ? "admin-post" : ""}`}" id="comentario_${item.id}">
                <div class="comment-header">
                    <div class="comment-author-box">
                        <span style="display:inline-flex; align-items:center;" title="${nacaoObj.nome}">${nacaoObj.svg}</span>
                        <strong style="color:${isAdm ? "#F2B400" : "#fff"}; font-size:13px;">${item.nickname}</strong>
                        ${badgePatente}
                    </div>
                    <span style="font-size:11px; color:#777; font-family:monospace;">${item.criado_em}</span>
                </div>
                <div class="comment-body">${formatarTextoTatico(item.conteudo, basePath)}</div>
                <div class="comment-actions">
                    <button type="button" class="btn-vote-tactical ${classeLike}" id="btnLike_${item.id}" onclick="window.votarComentarioWiki(${item.id}, 1)">
                        👍 <span id="countLike_${item.id}">${item.likes}</span>
                    </button>
                    <button type="button" class="btn-vote-tactical ${classeDislike}" id="btnDislike_${item.id}" onclick="window.votarComentarioWiki(${item.id}, -1)">
                        👎 <span id="countDislike_${item.id}">${item.dislikes}</span>
                    </button>
                    ${btnResponderHtml}
                    ${btnExcluirHtml}
                </div>
                ${caixaRespostaHtml}
                ${respostasFilhasHtml}
            </div>
        `;
    };

    async function carregarComentarios() {
        try {
            const res = await apiTatica(`${basePath}php/api/comunidade_wiki.php?acao=listar_comentarios&tanque_id=${tankId}`);
            if (res.status === "success") {
                badgeTotal.textContent = `${res.total || 0} RELATÓRIO(S)`;
                if (!res.comentarios || res.comentarios.length === 0) {
                    listaComEl.innerHTML = '<div style="text-align:center; padding:25px; color:#777; font-style:italic;">Nenhum relatório de combate registrado para este blindado. Seja o primeiro comandante a deixar uma análise!</div>';
                    return;
                }
                listaComEl.innerHTML = res.comentarios.map(c => renderizarCardItem(c, false)).join("");
            }
        } catch (err) {
            listaComEl.innerHTML = '<div style="text-align:center; padding:20px; color:#ff4d4d;">Erro ao carregar os relatórios de combate.</div>';
        }
    }

    // Funções Globais de Interação (Responder, Votar Like/Dislike e Excluir)
    window.abrirCaixaResposta = (comentarioId) => {
        const box = document.getElementById(`boxResposta_${comentarioId}`);
        if (box) {
            box.style.display = box.style.display === "none" ? "block" : "none";
            const input = document.getElementById(`inputResposta_${comentarioId}`);
            if (input) input.focus();
        }
    };

    window.enviarRespostaWiki = async (parentId) => {
        const input = document.getElementById(`inputResposta_${parentId}`);
        if (!input || !input.value.trim()) return;

        const fd = new FormData();
        fd.append("acao", "publicar_comentario");
        fd.append("tanque_id", tankId);
        fd.append("parent_id", parentId);
        fd.append("conteudo", input.value.trim());

        try {
            const res = await apiTatica(`${basePath}php/api/comunidade_wiki.php`, fd);
            mostrarAvisoComentario(res.message, res.status === "success");
            if (res.status === "success") carregarComentarios();
        } catch (e) {
            mostrarAvisoComentario("Erro ao enviar resposta.", false);
        }
    };

    window.votarComentarioWiki = async (comentarioId, voto) => {
        if (localStorage.getItem("isAuth") !== "true") {
            document.getElementById("loginModal").classList.add("ativo");
            return;
        }
        const fd = new FormData();
        fd.append("acao", "votar_comentario");
        fd.append("comentario_id", comentarioId);
        fd.append("voto", voto);

        try {
            const res = await apiTatica(`${basePath}php/api/comunidade_wiki.php`, fd);
            if (res.status === "success") {
                document.getElementById(`countLike_${comentarioId}`).textContent = res.likes;
                document.getElementById(`countDislike_${comentarioId}`).textContent = res.dislikes;
                const btnL = document.getElementById(`btnLike_${comentarioId}`);
                const btnD = document.getElementById(`btnDislike_${comentarioId}`);
                btnL.classList.toggle("voted-like", res.meu_voto === 1);
                btnD.classList.toggle("voted-dislike", res.meu_voto === -1);
            }
        } catch (e) {}
    };

    window.excluirComentarioWiki = async (comentarioId) => {
        if (!confirm("Confirma a exclusão deste relatório de combate?")) return;
        const fd = new FormData();
        fd.append("acao", "excluir_comentario");
        fd.append("comentario_id", comentarioId);

        try {
            const res = await apiTatica(`${basePath}php/api/comunidade_wiki.php`, fd);
            mostrarAvisoComentario(res.message, res.status === "success");
            if (res.status === "success") carregarComentarios();
        } catch (e) {
            mostrarAvisoComentario("Erro ao excluir comentário.", false);
        }
    };

    montarCaixaEnvio();
    carregarComentarios();
}